--!nonstrict
-- ShadowScan 0.6.2 (Standalone Edition - deliverable)
-- GENERATED by tools/build_standalone.py from the standalone/ module set. Do not edit; edit the sources and rebuild.
-- Single-file, standalone, no runtime dependencies: no companion, no server, no encryption, no network.
-- This tool analyzes Luau source text you provide. It never executes the analyzed source.
local __factories = {}
local __cache = {}
local function __require(name)
	local c = __cache[name]
	if c ~= nil then return c end
	local f = __factories[name]
	if not f then error("ShadowScan: unknown module '" .. tostring(name) .. "'", 2) end
	local m = f(__require)
	__cache[name] = m
	return m
end
__factories["src.analyzer"] = function(require)
-- Turns observations into candidate findings. Pure function: same observations -> same findings.
-- The analyzer NEVER produces a verdict stronger than CANDIDATE. Only verdict.lua can, after a manifest-approved test.
-- 0.3.0: findings additionally carry a functional classification (hint-level) and an evidence-based risk score.
local util = require("src.util")
local rules = require("src.runtime_rules")
local classify = require("src.classify")
local risk = require("src.risk")

local A = {}

local WEAK_SEVERITY_CAP = "low"

function A.new_name_counts(observations)
	local counts = {}
	for _, o in ipairs(observations) do
		if rules.REMOTE_CLASSES[o.class_name] then
			local k = o.class_name .. "|" .. o.name
			counts[k] = (counts[k] or 0) + 1
		end
	end
	return counts
end

local function union_unknowns(hits)
	local seen, out = {}, {}
	for _, h in ipairs(hits) do
		for _, u in ipairs(h.unknowns or {}) do
			if not seen[u] then seen[u] = true; out[#out + 1] = u end
		end
	end
	return out
end

local function union_tests(hits)
	local seen, out = {}, {}
	for _, h in ipairs(hits) do
		for _, t in ipairs(h.tests or {}) do
			if not seen[t.test_type] then seen[t.test_type] = true; out[#out + 1] = { test_type = t.test_type, note = t.note } end
		end
	end
	return out
end

-- analyze(observations) -> findings (array)
function A.analyze(observations)
	local ctx = { name_counts = A.new_name_counts(observations) }
	local ordered = {}
	for _, o in ipairs(observations) do ordered[#ordered + 1] = o end
	table.sort(ordered, function(a, b)
		if a.path ~= b.path then return a.path < b.path end
		return a.obs_id < b.obs_id
	end)

	local findings = {}
	for _, obs in ipairs(ordered) do
		local hits = rules.evaluate(obs, ctx)
		if #hits > 0 then
			local primary = hits[1]
			local all_weak, sev, conf = true, nil, nil
			local seen_cat, secondary = { [primary.category] = true }, {}
			for _, h in ipairs(hits) do
				if rules.CATEGORY_INDEX[h.category] < rules.CATEGORY_INDEX[primary.category] then primary = h end
				if not h.weak then all_weak = false end
				sev = util.max_by_order(util.SEVERITY_ORDER, sev, h.severity)
				conf = util.max_by_order(util.CONFIDENCE_ORDER, conf, h.confidence)
			end
			for _, h in ipairs(hits) do
				if h.category ~= primary.category and not seen_cat[h.category] then
					seen_cat[h.category] = true
					secondary[#secondary + 1] = h.category
				end
			end
			table.sort(secondary, function(a, b) return rules.CATEGORY_INDEX[a] < rules.CATEGORY_INDEX[b] end)
			if all_weak then
				-- name / location / existence only: never above low severity and low confidence
				sev = util.min_by_order(util.SEVERITY_ORDER, sev, WEAK_SEVERITY_CAP)
				conf = "low"
			end
			local evidence, rationale, seen_r = {}, {}, {}
			for _, h in ipairs(hits) do
				evidence[#evidence + 1] = { kind = h.kind, rule_id = h.rule_id, detail = h.evidence }
				if not seen_r[h.rationale] then seen_r[h.rationale] = true; rationale[#rationale + 1] = h.rationale end
			end
			findings[#findings + 1] = {
				object_name = obs.name,
				object_class = obs.class_name,
				object_path = obs.path,
				observation_ids = { obs.obs_id },
				category = primary.category,
				secondary_categories = secondary,
				evidence = evidence,
				rationale = table.concat(rationale, " "),
				severity = sev,
				confidence = conf,
				unknowns = union_unknowns(hits),
				suggested_tests = union_tests(hits),
				verdict = "CANDIDATE",
				test_run_ids = {},
			}
			findings[#findings].classification = classify.classify(obs)
			findings[#findings].risk = risk.score(findings[#findings])
		end
	end
	table.sort(findings, function(a, b)
		if a.object_path ~= b.object_path then return a.object_path < b.object_path end
		return a.category < b.category
	end)
	for i, f in ipairs(findings) do f.finding_id = string.format("SS-%04d", i) end
	return findings
end

function A.summarize(findings)
	local by_cat, by_sev = {}, { informational = 0, low = 0, medium = 0, high = 0 }
	for _, c in ipairs(rules.CATEGORIES) do by_cat[c] = 0 end
	for _, f in ipairs(findings) do
		by_cat[f.category] += 1
		by_sev[f.severity] += 1
	end
	return { total = #findings, by_category = by_cat, by_severity = by_sev }
end

return A
end
__factories["src.app"] = function(require)
-- ShadowScan 0.6.0 application: 8 pages (Dashboard, Explorer, Findings, Graph, Session, Static,
-- Reports, Settings) on a top-bar + sidebar + content layout. Layout is computed as pure data here and
-- painted by ui.lua's diff renderer. All controls dispatch real actions; no decorative buttons.
local config = require("src.config")
local util = require("src.util")
local ui = require("src.ui")

local A = {}
A.__index = A

local PAD, SP = 16, { xs = 4, sm = 8, md = 12, lg = 16 }
local PAGES = { "dashboard", "explorer", "findings", "graph", "session", "static", "reports", "settings" }
local PAGE_LABELS = { Dashboard = "dashboard", ["Remote Explorer"] = "explorer", Findings = "findings",
	Graph = "graph", ["Session Intelligence"] = "session", ["Static Analyzer"] = "static",
	Reports = "reports", Settings = "settings" }
local SEV_COLOR = { CRITICAL = "error", HIGH = "warning", MEDIUM = "warning", LOW = "text_muted", INFORMATIONAL = "text_muted" }

function A.new(session, static, deps)
	local self = setmetatable({}, A)
	self.session = session
	self.static = static            -- { analyze(source, name) -> result; report_text(source, name) }
	self.deps = deps
	self.caps = deps.caps or util.detect_caps({})
	self.viewport = deps.viewport or { w = 1100, h = 720 }
	self.page = "dashboard"
	self.selected_path = nil
	self.finding_index = nil
	self.explorer_query = ""
	self.explorer_class = nil
	self.explorer_page = 1
	self.findings_filter = nil
	self.static_source = ""
	self.static_source_name = "pasted source"
	self.static_result = nil
	self.feedback = nil
	self.compare_text = ""
	self.compare_result = nil
	self.report_text = nil
	self.busy = false
	self.minimized = false
	self.ui_transition = false
	self.destroyed = false
	return self
end

function A:set_feedback(tone, label, text)
	self.feedback = { tone = tone, label = label, text = text }
end

-- ---------------------------------------------------------------- shared builders
local function txt(id, x, y, w, h, s, o)
	o = o or {}
	return { id = id, kind = "text", rect = { x = x, y = y, w = w, h = h }, text = s,
		size = o.size or 12, font = o.font, color = o.color or "text", align = o.align,
		wrap = o.wrap ~= false, truncate = o.truncate, fill = o.fill }
end

local function btn(id, x, y, w, h, s, o)
	o = o or {}
	return { id = id, kind = "button", rect = { x = x, y = y, w = w, h = h }, text = s,
		style = o.style or "secondary", action = o.action, disabled = o.disabled,
		loading = o.loading, busy_text = o.busy_text }
end

local function panel(id, x, y, w, h, title)
	local node = { id = id, kind = "frame", rect = { x = x, y = y, w = w, h = h }, fill = "panel",
		stroke = "border", radius = 4, children = {} }
	if title then
		node.children[#node.children + 1] = txt(id .. ".t", 12, 8, w - 24, 16, title, { size = 12, font = "ui_bold", color = "text" })
	end
	return node
end

local function sev_cell(id, x, y, w, label, count)
	local color = SEV_COLOR[label] or "text_muted"
	return { id = id, kind = "frame", rect = { x = x, y = y, w = w, h = 52 }, fill = "panel_raised", stroke = "border", radius = 4,
		children = {
			txt(id .. ".l", 10, 8, w - 20, 14, label, { size = 10, color = color, font = "ui_bold" }),
			txt(id .. ".v", 10, 24, w - 20, 22, tostring(count), { size = 18, font = "ui_bold" }),
		} }
end

-- explorer rows: filtered + sorted inventory (lazy: paged by the caller)
local EXPLORER_PAGE_SIZE = 12

function A:explorer_rows()
	local rows = {}
	if not self.session or not self.session.inventory then return rows end
	if not self.session or not self.session.inventory then return rows end
	local rows = {}
	local q = string.lower(self.explorer_query or "")
	for path, rec in pairs(self.session.inventory) do
		local match = true
		if self.explorer_class and rec.class_name ~= self.explorer_class then match = false end
		if match and q ~= "" then
			local hay = string.lower(path .. " " .. rec.class_name)
			if not string.find(hay, q, 1, true) then match = false end
		end
		if match then rows[#rows + 1] = rec end
	end
	table.sort(rows, function(a, b)
		local fa, fb = self.session.findings_by_path and self.session.findings_by_path[a.path]
		local pa = (fa and fa.risk and fa.risk.priority) or 0
		local fb2 = self.session.findings_by_path and self.session.findings_by_path[b.path]
		local pb = (fb2 and fb2.risk and fb2.risk.priority) or 0
		if pa ~= pb then return pa > pb end
		return a.path < b.path
	end)
	return rows
end

-- ---------------------------------------------------------------- pages
function A:page_dashboard(x, y, w, children)
	local s = self.session
	children[#children + 1] = panel("dash.inv", x, y, w, 78, "Inventory (client-visible; not a complete server inventory)")
	local counts = { RemoteEvent = 0, RemoteFunction = 0, UnreliableRemoteEvent = 0 }
	for _, rec in pairs(s.inventory) do
		if counts[rec.class_name] then counts[rec.class_name] += 1 end
	end
	local cw = math.floor((w - 2 * PAD - 2 * SP.sm) / 3)
	for i, c in ipairs({ { "RemoteEvent", counts.RemoteEvent }, { "RemoteFunction", counts.RemoteFunction }, { "UnreliableRemoteEvent", counts.UnreliableRemoteEvent } }) do
		children[#children + 1] = sev_cell("dash.inv." .. i, x + PAD + (i - 1) * (cw + SP.sm), y + 26, cw, c[1], c[2])
	end
	y += 78 + SP.lg

	local total_findings = #s.findings
	local sev = { CRITICAL = 0, HIGH = 0, MEDIUM = 0, LOW = 0, INFORMATIONAL = 0 }
	for _, f in ipairs(s.findings) do
		local key = string.upper(tostring(f.severity or "UNCLASSIFIED"))
		if sev[key] ~= nil then sev[key] += 1 end
	end
	children[#children + 1] = panel("dash.find", x, y, w, 108, "Findings by severity (runtime candidates — not confirmed vulnerabilities)")
	for i, c in ipairs({ { "CRITICAL", sev.CRITICAL }, { "HIGH", sev.HIGH }, { "MEDIUM", sev.MEDIUM }, { "LOW", sev.LOW }, { "INFO", sev.INFORMATIONAL } }) do
		local cw5 = math.floor((w - 2 * PAD - 4 * SP.sm) / 5)
		children[#children + 1] = sev_cell("dash.find." .. i, x + PAD + (i - 1) * (cw5 + SP.sm), y + 26, cw5, c[1], c[2])
	end
	children[#children + 1] = txt("dash.risk", x + PAD, y + 84, w - 2 * PAD, 16,
		total_findings > 0 and "Review findings in the Findings page; priority is not a confirmation." or "No candidates yet — run a scan.",
		{ size = 11, color = "text_muted" })
	y += 108 + SP.lg

	children[#children + 1] = panel("dash.last", x, y, w, 78, "Last scan & live observation")
	local last = s.last_scan
	local live = s:live_info()
	local last_text = last and string.format("%s | %d visited | %d observed | %d findings", last.status, last.visited, last.observed, last.findings)
		or "No scan yet — press Scan in the top bar."
	local live_text = live.running and "running (new objects are added automatically)" or "off"
	children[#children + 1] = txt("dash.last.scan", x + PAD, y + 28, w - 2 * PAD, 16, last_text, { size = 11 })
	children[#children + 1] = txt("dash.last.live", x + PAD, y + 48, w - 2 * PAD, 16,
		"Live observation: " .. live_text .. " | profile: " .. s.profile .. " | scans: " .. tostring(s.stats.scans), { size = 11, color = "text_muted" })
	y += 78
	return y
end

function A:page_explorer(x, y, w, children)
	children[#children + 1] = txt("ex.l", x, y, 60, 16, "Search:", { size = 11, color = "text_muted" })
	children[#children + 1] = { id = "ex.q", kind = "input", rect = { x = x + 64, y = y - 2, w = math.floor(w * 0.4), h = 26 },
		text = self.explorer_query, placeholder = "name or path...", action = { name = "explorer.query" } }
	-- 0.6.1 FIX: the 0.6.0 array was { nil, "RemoteEvent", ... } -- ipairs stops at the first nil
	-- (index 1), so NOT A SINGLE class-filter button was ever created. The array now carries
	-- {label, value} entries; a nil VALUE ("All") is expressed without a nil ARRAY SLOT.
	local classes = {
		{ label = "All", value = nil },
		{ label = "RemoteEvent", value = "RemoteEvent" },
		{ label = "RemoteFunction", value = "RemoteFunction" },
		{ label = "UnreliableRemoteEvent", value = "UnreliableRemoteEvent" },
	}
	local cx = x + 64 + math.floor(w * 0.4) + SP.md
	for i, cdef in ipairs(classes) do
		local cls = cdef.value
		local cw = math.max(56, 24 + #cdef.label * 7)
		children[#children + 1] = btn("ex.cls." .. i, cx, y - 4, cw, 26, cdef.label,
			{ style = self.explorer_class == cls and "primary" or "secondary",
			  action = { name = "explorer.class", arg = cls } })
		cx += cw + SP.xs
	end
	y += 30

	local rows = self:explorer_rows()
	local page_size = EXPLORER_PAGE_SIZE
	local page_count = math.max(1, math.ceil(#rows / page_size))
	self.explorer_page = math.min(math.max(self.explorer_page, 1), page_count)
	local first = (self.explorer_page - 1) * page_size + 1
	local total_matching = 0
	for _ in ipairs(rows) do total_matching += 1 end
	children[#children + 1] = txt("ex.count", x, y, math.floor(w * 0.5), 16,
		string.format("%d object(s) match — showing %d-%d of page %d/%d", #rows, first, math.min(first + page_size - 1, #rows), self.explorer_page, page_count),
		{ size = 11, color = "text_muted" })
	local bx = x + w - 190
	children[#children + 1] = btn("ex.prev", bx, y - 4, 90, 26, "Previous", { disabled = self.explorer_page <= 1, action = { name = "explorer.page", arg = -1 } })
	children[#children + 1] = btn("ex.next", bx + 96, y - 4, 90, 26, "Next", { disabled = self.explorer_page >= page_count, action = { name = "explorer.page", arg = 1 } })
	y += 26

	local row_h = 40
	local list_h = math.min(page_size, math.max(1, #rows - first + 1)) * (row_h + SP.xs)
	list_h = math.max(list_h, row_h)
	local list = panel("ex.list", x, y, w, list_h + 8)
	for i = 0, page_size - 1 do
		local rec = rows[first + i]
		if not rec then break end
		local selected = self.selected_path == rec.path
		local f = self.session.findings_by_path and self.session.findings_by_path[rec.path]
		local prio = 0
		if f and f.risk and f.risk.priority then prio = f.risk.priority end
		local row = { id = "ex.row." .. i, kind = "frame", rect = { x = 4, y = 4 + i * (row_h + SP.xs), w = w - 8, h = row_h },
			fill = selected and "accent_soft" or (i % 2 == 0 and "panel_raised" or "panel"), children = {} }
		row.children[#row.children + 1] = txt("nm", 8, 4, math.floor(w * 0.45), 16, rec.name, { size = 12, font = "ui_bold", truncate = true })
		row.children[#row.children + 1] = txt("cl", 8, 21, math.floor(w * 0.45), 14, rec.class_name, { size = 10, color = "text_muted" })
		row.children[#row.children + 1] = txt("pt", math.floor(w * 0.46), 4, math.floor(w * 0.38), 30, rec.path, { size = 10, color = "text_muted", truncate = true })
		row.children[#row.children + 1] = txt("pr", w - 92, 4, 80, 16, "priority " .. tostring(prio), { size = 10, align = "right",
			color = prio >= 45 and "error" or (prio >= 20 and "warning" or "text_muted") })
		row.children[#row.children + 1] = btn("sel", w - 116, 8, 46, 24, selected and "Open" or "Select",
			{ style = selected and "primary" or "secondary", action = { name = "explorer.select", arg = rec.path } })
		row.children[#row.children + 1] = btn("cp", w - 62, 8, 46, 24, "Path", { action = { name = "explorer.copypath", arg = rec.path } })
		list.children[#list.children + 1] = row
	end
	children[#children + 1] = list
	y += list_h + 12 + SP.sm

	-- inspector for the selected object
	if self.selected_path then
		local rec = self.session.inventory[self.selected_path]
		if rec then
			local f = self.session.findings_by_path and self.session.findings_by_path[rec.path]
			local insp = panel("ex.insp", x, y, w, 150, "Inspector")
			local lines = {
				string.format("Path: %s", rec.path),
				string.format("Class: %s | first seen: %s | last seen: %s", rec.class_name, tostring(rec.first_seen), tostring(rec.last_seen)),
				rec.stale and ("STALE since " .. tostring(rec.stale_since) .. " — not observed in the most recent scan; kept for history, not a current observation.")
					or "Current: observed in the most recent scan.",
				f and string.format("Classification: %s (%s) | priority %d | confidence %s | status %s",
					f.classification and f.classification.family or "unknown",
					f.classification and f.classification.confidence or "-",
					f.risk and f.risk.priority or 0,
					f.risk and f.risk.evidence_confidence or "low",
					f.risk and f.risk.verification_status or "unverified")
					or "Classification: unknown — no finding generated for this object",
				"Server-side implementation is not visible from the client; names and metadata are hints, not facts.",
			}
			for i, l in ipairs(lines) do
				insp.children[#insp.children + 1] = txt("l" .. i, 12, 26 + (i - 1) * 18, w - 2 * PAD - 24, 16, l,
					{ size = 11, color = i >= 4 and "text_muted" or "text" })
			end
			children[#children + 1] = insp
			y += 150 + SP.sm
		end
	end
	return y
end

function A:page_findings(x, y, w, children)
	-- 0.6.1 FIX: same nil-first-array defect as the Explorer filters -- { nil, "runtime", "static" }
	-- rendered ZERO origin buttons. Entries now carry {label, value}.
	local filters = {
		{ label = "All", value = nil },
		{ label = "Runtime", value = "runtime" },
		{ label = "Static", value = "static" },
	}
	local fx = x
	children[#children + 1] = txt("fi.l", x, y, 90, 16, "Origin:", { size = 11, color = "text_muted" })
	fx = x + 70
	for i, fdef in ipairs(filters) do
		local o = fdef.value
		children[#children + 1] = btn("fi.o." .. i, fx, y - 4, 80, 26, fdef.label,
			{ style = self.findings_filter == o and "primary" or "secondary", action = { name = "findings.filter", arg = o } })
		fx += 86
	end
	y += 30
	local findings = {}
	for _, f in ipairs(self.session.findings) do
		if not self.findings_filter or f.origin == self.findings_filter then
			findings[#findings + 1] = f
		end
	end
	if self.static_result and (not self.findings_filter or self.findings_filter == "static") then
		for _, f in ipairs(self.static_result.findings) do
			findings[#findings + 1] = {
				origin = "static", rule_id = f.rule_id, title = f.title, severity = f.severity,
				confidence = f.confidence, line = f.line, evidence = f.evidence,
				explanation = f.explanation, impact = f.impact, recommendation = f.recommendation,
				object_path = self.static_source_name .. " line " .. f.line,
			}
		end
	end
	table.sort(findings, function(a, b)
		local rank = { CRITICAL = 5, HIGH = 4, MEDIUM = 3, LOW = 2, INFORMATIONAL = 1 }
		if rank[a.severity] ~= rank[b.severity] then return rank[a.severity] > rank[b.severity] end
		return (a.rule_id or "") < (b.rule_id or "")
	end)
	children[#children + 1] = txt("fi.count", x, y, w - 2 * PAD, 16, #findings .. " finding(s)", { size = 11, color = "text_muted" })
	y += 22
	if #findings == 0 then
		-- 0.6.1 FIX: the 0.6.0 pattern assigned children[#children+1] = panel(...) and THEN wrote
		-- children[#children+1].children -- but #children had already grown, so it indexed the NEXT
		-- (nil) slot and CRASHED the page whenever the filtered findings list was empty.
		local empty = panel("fi.empty", x, y, w, 50)
		empty.children = { txt("m", 12, 12, w - 2 * PAD - 24, 30, "No findings. That is not a guarantee of safety — see the limitations.", { size = 11, color = "text_muted" }) }
		children[#children + 1] = empty
		return y + 60
	end
	for i, f in ipairs(findings) do
		local origin_label = f.origin == "static" and "STATIC" or "RUNTIME"
		local display_title = f.title or (f.category or "Finding") .. (f.classification and f.classification.family and (" [" .. f.classification.family .. "]") or "")
		local rid = f.rule_id or (f.evidence and type(f.evidence) == "table" and f.evidence[1] and f.evidence[1].rule_id) or f.finding_id or "N/A"
		local evidence_text = f.evidence
		if type(evidence_text) == "table" then
			local parts = {}
			for _, e in ipairs(evidence_text) do
				parts[#parts + 1] = tostring(e.kind or "") .. ": " .. tostring(e.detail or "")
			end
			evidence_text = table.concat(parts, "; ")
		end
		local expl = f.explanation or f.rationale or ""
		local rec = f.recommendation or (f.suggested_tests and f.suggested_tests[1] and f.suggested_tests[1].note) or "Review with the developer."
		local blk = panel("fi." .. i, x, y, w, 116)
		blk.children[#blk.children + 1] = txt("t", 12, 8, w - 2 * PAD - 120, 16, display_title, { size = 12, font = "ui_bold" })
		blk.children[#blk.children + 1] = { id = "sev", kind = "text", rect = { x = w - PAD - 150, y = 8, w = 138, h = 16 },
			text = origin_label .. " | " .. f.severity, size = 10, color = SEV_COLOR[f.severity] or "text_muted", align = "right", font = "ui_bold" }
		blk.children[#blk.children + 1] = txt("m", 12, 26, w - 2 * PAD - 24, 14,
			tostring(rid) .. " | " .. tostring(f.object_path or "") .. " | confidence " .. tostring(f.confidence), { size = 10, color = "text_muted" })
		blk.children[#blk.children + 1] = txt("ev", 12, 42, w - 2 * PAD - 24, 16, tostring(evidence_text), { size = 11, font = "mono", truncate = true })
		blk.children[#blk.children + 1] = txt("ex", 12, 60, w - 2 * PAD - 24, 28, tostring(expl), { size = 11, color = "text_muted" })
		blk.children[#blk.children + 1] = txt("rc", 12, 90, w - 2 * PAD - 24, 14, "Recommendation: " .. tostring(rec), { size = 10, color = "text" })
		children[#children + 1] = blk
		y += 124
		if i >= 25 then
			children[#children + 1] = txt("fi.more", x, y, w - 2 * PAD, 16, "Showing the first 25 findings — see the full report for the rest.", { size = 11, color = "text_muted" })
			y += 22
			break
		end
	end
	return y
end

function A:page_graph(x, y, w, children)
	local g = self.session.graph
	-- 0.6.1: honest scope statement. This page renders a BOUNDED CONTAINER SUMMARY (child-of
	-- counts per parent); it does not draw a node/edge visualization. Renamed accordingly rather
	-- than implying a rendered relationship graph.
	children[#children + 1] = txt("gr.hint", x, y, w - 2 * PAD, 16,
		"Bounded container summary: CHILD_OF counts per parent. No node/edge visualization is rendered in this build.",
		{ size = 11, color = "text_muted" })
	y += 22
	if not g then
		-- 0.6.1 FIX: same nil-slot crash as the findings empty state (page crashed before any scan)
		local empty = panel("gr.empty", x, y, w, 44)
		empty.children = { txt("m", 12, 12, w - 2 * PAD - 24, 24, "No graph yet — run a scan first.", { size = 11, color = "text_muted" }) }
		children[#children + 1] = empty
		return y + 54
	end
	children[#children + 1] = txt("gr.stats", x, y, w - 2 * PAD, 16,
		string.format("%d remote(s) in %d container(s) — nodes %d, edges %d%s", g.stats.remotes, g.stats.containers,
			g.stats.nodes, g.stats.edges, g.stats.truncated and " (truncated)" or ""), { size = 11, color = "text_muted" })
	y += 22
	local containers = {}
	for _, n in ipairs(g.nodes) do
		if n.kind == "container" then containers[#containers + 1] = n end
	end
	table.sort(containers, function(a, b) return a.path < b.path end)
	local row_h = 36
	local shown = math.min(#containers, 14)
	for i = 1, shown do
		local c = containers[i]
		local member_count = 0
		for _, e in ipairs(g.edges) do
			if e.kind == "child_of" and e.to == c.id then member_count += 1 end
		end
		local blk = { id = "gr." .. i, kind = "frame", rect = { x = x, y = y, w = w - 2 * PAD, h = row_h },
			fill = i % 2 == 0 and "panel_raised" or "panel", children = {} }
		blk.children[#blk.children + 1] = txt("p", 12, 4, math.floor(w * 0.62), 16, c.path, { size = 11, truncate = true })
		blk.children[#blk.children + 1] = txt("n", w - PAD - 200, 4, 90, 16, tostring(member_count) .. " remote(s)", { size = 11, color = "text_muted", align = "right" })
		blk.children[#blk.children + 1] = txt("k", w - PAD - 100, 4, 90, 16, "CHILD_OF edges", { size = 10, color = "text_disabled", align = "right" })
		children[#children + 1] = blk
		y += row_h + SP.xs
	end
	if #containers > shown then
		children[#children + 1] = txt("gr.more", x, y, w - 2 * PAD, 16,
			string.format("%d more container(s) — bounded rendering; refine with a scan of specific roots.", #containers - shown),
			{ size = 11, color = "text_muted" })
		y += 22
	end
	return y
end

function A:page_session(x, y, w, children)
	children[#children + 1] = txt("se.hint", x, y, w - 2 * PAD, 16,
		"Snapshots capture the client-visible remote surface. Disappearance does not prove deletion (replication/streaming).",
		{ size = 11, color = "text_muted" })
	y += 22
	local bx = x
	children[#children + 1] = btn("se.snap", bx, y, 140, 30, "Create Snapshot", { style = "primary", action = { name = "session.snapshot" }, disabled = self.busy })
	bx += 146
	children[#children + 1] = btn("se.save", bx, y, 110, 30, "Save Latest", { action = { name = "session.save" }, disabled = #self.session.snapshots == 0 })
	bx += 116
	children[#children + 1] = btn("se.cmp", bx, y, 190, 30, "Compare Previous:Latest", { action = { name = "session.compare" }, disabled = #self.session.snapshots < 2 })
	bx += 196
	-- 0.6.1: explicit PREVIOUS snapshot selection (< >) against the fixed LATEST; 0.6.0 "compared"
	-- the current inventory against a snapshot and called session:compare, which did not exist.
	if #self.session.snapshots >= 2 then
		local idx = self.compare_prev_idx or (#self.session.snapshots - 1)
		if idx < 1 or idx > #self.session.snapshots - 1 then idx = #self.session.snapshots - 1 end
		self.compare_prev_idx = idx
		children[#children + 1] = btn("se.cpv", bx, y, 26, 30, "<", { action = { name = "compare.select", arg = idx - 1 }, disabled = idx <= 1 })
		children[#children + 1] = txt("se.cpl", bx + 30, y + 8, 90, 16, "prev " .. idx .. "/" .. (#self.session.snapshots - 1), { size = 10, color = "text_muted", align = "center" })
		children[#children + 1] = btn("se.cpn", bx + 122, y, 26, 30, ">", { action = { name = "compare.select", arg = idx + 1 }, disabled = idx >= #self.session.snapshots - 1 })
	end
	y += 38
	children[#children + 1] = txt("se.count", x, y, w - 2 * PAD, 16,
		tostring(#self.session.snapshots) .. " in-memory snapshot(s) (bounded to 10)", { size = 11, color = "text_muted" })
	y += 22
	local snap = self.session.snapshots[#self.session.snapshots]
	if snap then
		children[#children + 1] = txt("se.latest", x, y, w - 2 * PAD, 16,
			"Latest: " .. tostring(snap.created_utc) .. " — " .. tostring(snap.remote_count) .. " remote(s)", { size = 11 })
		y += 22
	end
	local d = self.compare_result
	if d then
		children[#children + 1] = txt("se.cmp", x, y, w - 2 * PAD, 16,
			string.format("Comparison: +%d added, -%d removed, ~%d changed, %d renamed, %d reparented, %d possibly moved (vs %s)",
				d.added_count, d.removed_count, d.changed_count, d.renamed_count, d.reparented_count, d.moved_count,
				tostring(d.previous_created_utc)), { size = 11, font = "ui_bold" })
		y += 22
		children[#children + 1] = txt("se.note", x, y, w - 2 * PAD, 16, d.note, { size = 10, color = "text_muted" })
		y += 22
		local rows = {}
		local function safe_row(kind, obj, path_key, from_key, to_key)
			local p = tostring(obj[path_key] or obj[from_key] or "")
			if from_key and obj[to_key] then p = tostring(obj[from_key]) .. " -> " .. tostring(obj[to_key]) end
			return { kind, tostring(obj.name or obj.class_name or ""), p, tostring(obj.confidence or "low") }
		end
		for _, a in ipairs(d.ADDED) do rows[#rows + 1] = safe_row("ADDED", a, "path") end
		for _, r in ipairs(d.REMOVED) do rows[#rows + 1] = safe_row("REMOVED", r, "path") end
		for _, c in ipairs(d.METADATA_CHANGED) do rows[#rows + 1] = safe_row("CHANGED", c, "path") end
		for _, r in ipairs(d.RENAMED) do rows[#rows + 1] = safe_row("RENAMED", r, nil, "from", "to") end
		for _, r in ipairs(d.REPARENTED) do rows[#rows + 1] = safe_row("REPARENTED", r, nil, "from", "to") end
		for _, r in ipairs(d.POSSIBLY_MOVED) do rows[#rows + 1] = safe_row("MOVED?", r, nil, "from", "to") end
		for i = 1, math.min(#rows, 20) do
			local r = rows[i]
			local color = r[1] == "ADDED" and "success" or (r[1] == "REMOVED" and "error" or "warning")
			children[#children + 1] = txt("se.r" .. i, x, y, w - 2 * PAD, 16,
				string.format("%-10s %-9s %s", r[1], r[3], r[2]), { size = 10, color = color, font = "mono", truncate = true })
			y += 18
		end
	end
	return y
end

function A:page_static(x, y, w, children)
	children[#children + 1] = txt("st.hint", x, y, w - 2 * PAD, 16,
		"Optional mode: analyze Luau source you provide. Evidence is labeled STATIC and stays separate from runtime findings. The source is never executed.",
		{ size = 11, color = "text_muted" })
	y += 22
	children[#children + 1] = { id = "st.name", kind = "input", rect = { x = x, y = y, w = 240, h = 26 },
		text = self.static_source_name, placeholder = "source name", action = { name = "static.name" } }
	y += 32
	children[#children + 1] = { id = "st.box", kind = "input", rect = { x = x, y = y, w = w - 2 * PAD, h = 110 },
		text = self.static_source, placeholder = "-- paste the authorized Luau source here", mono = true, multiline = true,
		action = { name = "static.text" } }
	y += 116 + SP.sm
	children[#children + 1] = btn("st.scan", x + w - 2 * PAD - 110, y, 110, 30, "Analyze Source",
		{ style = "primary", action = { name = "static.scan" }, loading = self.busy })
	y += 36
	local res = self.static_result
	if res then
		local counts = res.summary.counts
		children[#children + 1] = txt("st.sum", x, y, w - 2 * PAD, 16,
			string.format("%s | %d line(s) | %d rule(s) | findings: %d (C:%d H:%d M:%d L:%d I:%d)",
				res.status, res.lines_analyzed, res.rules_evaluated, res.summary.total,
				counts.CRITICAL or 0, counts.HIGH or 0, counts.MEDIUM or 0, counts.LOW or 0, counts.INFORMATIONAL or 0),
			{ size = 11, font = "ui_bold" })
		y += 22
		if res.partial_reason then
			children[#children + 1] = txt("st.partial", x, y, w - 2 * PAD, 16, "PARTIAL: " .. res.partial_reason, { size = 10, color = "warning" })
			y += 20
		end
		for i, f in ipairs(res.findings) do
			if i > 10 then
				children[#children + 1] = txt("st.more", x, y, w - 2 * PAD, 16, "First 10 static findings shown — see the report for the rest.", { size = 10, color = "text_muted" })
				y += 20
				break
			end
			children[#children + 1] = txt("st.f" .. i, x, y, w - 2 * PAD, 30,
				string.format("[%s] %s — %s (line %d, %s): %s", f.severity, f.rule_id, f.title, f.line, f.confidence, f.evidence),
				{ size = 10, color = SEV_COLOR[f.severity] or "text", font = "mono" })
			y += 32
		end
	end
	return y
end

