	y += 84 + SP.lg
	children[#children + 1] = panel("set.reset", x, y, w, 70, "Session data")
	children[#children + 1] = btn("set.reset.b", x + PAD, y + 30, 130, 26, "Reset Session", { style = "danger", action = { name = "settings.reset" } })
	children[#children + 1] = txt("set.reset.h", x + PAD + 140, y + 34, w - 2 * PAD - 156, 16,
