function A:build_scene()
	local vw, vh = self.viewport.w, self.viewport.h
	if self.minimized then
		local mini_w = math.min(340, math.max(260, vw - 24))
		local mini_x = math.max(12, vw - mini_w - 24)
		local root = { id = "root", kind = "frame", rect = { x = mini_x, y = 20, w = mini_w, h = 44 },
			fill = "bg", stroke = "border", radius = 7, clip = true, animate = self.ui_transition, children = {} }
		local bar = { id = "bar", kind = "frame", rect = { x = 0, y = 0, w = mini_w, h = 44 }, fill = "sidebar", children = {} }
		bar.children[#bar.children + 1] = { id = "logo", kind = "frame", rect = { x = 12, y = 15, w = 14, h = 14 }, fill = "accent", radius = 3 }
		bar.children[#bar.children + 1] = txt("bar.title", 34, 8, math.max(100, mini_w - 160), 18,
			config.UI_TITLE .. " minimized", { size = 13, font = "ui_bold" })
		bar.children[#bar.children + 1] = btn("bar.restore", mini_w - 92, 7, 46, 30, "Open",
			{ style = "primary", action = { name = "ui.restore" } })
		bar.children[#bar.children + 1] = btn("bar.close", mini_w - 40, 7, 32, 30, "×",
			{ style = "danger", action = { name = "ui.close" } })
		root.children[#root.children + 1] = bar
		return root
	end

	local W = math.max(720, math.min(1180, vw - 40))
	local root = { id = "root", kind = "frame", rect = { x = math.floor((vw - W) / 2), y = 20, w = W, h = math.max(420, vh - 40) },
		fill = "bg", stroke = "border", radius = 6, clip = true, animate = self.ui_transition, children = {} }

	-- top bar
	local bar = { id = "bar", kind = "frame", rect = { x = 0, y = 0, w = W, h = 44 }, fill = "sidebar", children = {} }
	bar.children[#bar.children + 1] = { id = "logo", kind = "frame", rect = { x = 12, y = 15, w = 14, h = 14 }, fill = "accent", radius = 3 }
	bar.children[#bar.children + 1] = txt("bar.title", 34, 8, 200, 18, config.UI_TITLE .. " v" .. config.VERSION, { size = 14, font = "ui_bold" })
	bar.children[#bar.children + 1] = txt("bar.sub", 34, 26, 420, 12,
		self.busy and self.scan_progress and string.format("%s: %d object(s) visited...",
			self.scan_progress.stage == "done" and "finishing" or "scanning", self.scan_progress.done)
		or (self.busy and "scanning..." or config.UI_SUBTITLE), { size = 10, color = "text_muted" })
	-- 0.6.1: while a scan runs, the top-bar button becomes an ACTIVE CANCEL control (0.6.0 showed a
	-- dead "Scanning..." button: cancellation was impossible from the UI), and the subtitle line
	-- shows live progress (visited count), which is meaningful because the scan now yields
	-- cooperatively between batches so renders actually interleave with scanning.
	local scan_x = W - 266
	if self.busy then
		bar.children[#bar.children + 1] = btn("bar.cancel", scan_x, 7, 84, 30, "Cancel",
			{ style = "danger", action = { name = "scan.cancel" } })
	else
		bar.children[#bar.children + 1] = btn("bar.scan", scan_x, 7, 84, 30, "Scan",
			{ style = "primary", action = { name = "scan" } })
	end
	bar.children[#bar.children + 1] = btn("bar.live", W - 174, 7, 84, 30,
		self.session:live_info().running and "Live: On" or "Live: Off", { action = { name = "toggle.live" } })
	bar.children[#bar.children + 1] = btn("bar.min", W - 82, 7, 34, 30, "–",
		{ action = { name = "ui.minimize" } })
	bar.children[#bar.children + 1] = btn("bar.close", W - 42, 7, 34, 30, "×",
		{ style = "danger", action = { name = "ui.close" } })
	root.children[#root.children + 1] = bar

	-- sidebar
	local sb_w = 172
	local sb = { id = "sidebar", kind = "frame", rect = { x = 0, y = 44, w = sb_w, h = root.rect.h - 44 }, fill = "sidebar", children = {} }
	local sy = 12
	for _, label in ipairs({ "Dashboard", "Remote Explorer", "Findings", "Graph", "Session Intelligence", "Static Analyzer", "Reports", "Settings" }) do
		local key = PAGE_LABELS[label]
		sb.children[#sb.children + 1] = btn("nav." .. key, 6, sy, sb_w - 12, 32, label,
			{ style = self.page == key and "primary" or "secondary", action = { name = "nav", arg = key } })
		sy += 38
	end
	sb.children[#sb.children + 1] = txt("sb.status", 6, sy + 8, sb_w - 12, 40,
		"Last scan: " .. (self.session.last_scan and self.session.last_scan.status or "none")
		.. "\nObjects: " .. tostring(self.session.last_scan and self.session.last_scan.observed or 0), { size = 10, color = "text_muted" })
	root.children[#root.children + 1] = sb

	-- content
	local content_w = W - sb_w
	local content_x = sb_w
	local children_nodes = {}
	local y = 12 + 44
	local builder = self["page_" .. self.page] or self.page_dashboard
	y = builder(self, content_x + PAD, y, content_w - 2 * PAD, children_nodes)
	local scroll = { id = "content", kind = "scroll", rect = { x = content_x, y = 44, w = content_w, h = root.rect.h - 44 },
		fill = "bg", content_h = y + SP.lg, children = {} }
	for _, c in ipairs(children_nodes) do
		c.rect.x = c.rect.x - content_x
		c.rect.y = c.rect.y - 44
		scroll.children[#scroll.children + 1] = c
	end
	root.children[#root.children + 1] = scroll

	-- bottom status
	local status = { id = "status", kind = "frame", rect = { x = content_x, y = root.rect.h - 24, w = content_w, h = 24 }, fill = "sidebar", children = {} }
	local objects = 0
	for _ in pairs(self.session.inventory) do objects += 1 end
	status.children[#status.children + 1] = txt("s1", 10, 5, 260, 14,
		string.format("profile: %s | objects: %d | findings: %d", self.session.profile, objects, #self.session.findings), { size = 10, color = "text_muted" })
	status.children[#status.children + 1] = txt("s2", W - sb_w - 260, 5, 250, 14,
		"client-visible inventory only — not a complete server inventory", { size = 10, color = "text_disabled", align = "right" })
	root.children[#root.children + 1] = status
	return root
end

function A:render()
	if self.destroyed or not self.deps.factory then return end
	if not self.renderer then
		self.renderer = ui.new({ factory = self.deps.factory, parent = self.deps.gui_parent, env = self.deps.env,
			dispatch = function(action) self:dispatch(action) end })
	end
	local scene = self:build_scene()
	self.ui_transition = false
	self.renderer:render(scene)
end

function A:restore()
	if self.destroyed then return false end
	if self.minimized then
		self.minimized = false
		self.ui_transition = true
		self:render()
	end
	return true
end

function A:dispatch(action)
	local n = action.name
	if n == "nav" then self.page = action.arg
	elseif n == "scan" then self:do_scan()
	elseif n == "scan.cancel" then self:cancel_scan()
	elseif n == "compare.select" then self.compare_prev_idx = action.arg
	elseif n == "toggle.live" then self:toggle_live()
	elseif n == "explorer.query" then self.explorer_query = action.text or "" self.explorer_page = 1
	elseif n == "explorer.class" then self.explorer_class = action.arg self.explorer_page = 1
	elseif n == "explorer.page" then self.explorer_page = math.max(1, self.explorer_page + action.arg)
	elseif n == "explorer.select" then self.selected_path = action.arg
	elseif n == "explorer.copypath" then self:do_copy(action.arg, "object path")
	elseif n == "findings.filter" then self.findings_filter = action.arg
	elseif n == "session.snapshot" then self:do_snapshot()
	elseif n == "session.save" then self:do_save_snapshot()
	elseif n == "session.compare" then self:do_compare()
	elseif n == "static.text" then self.static_source = action.text or ""
	elseif n == "static.name" then self.static_source_name = action.text or ""
	elseif n == "static.scan" then self:do_static_scan()
	elseif n == "report.generate" then self:do_report()
	elseif n == "report.copy" then self:do_copy(self.report_text, "report")
	elseif n == "report.export" then self:do_export()
	elseif n == "settings.profile" then self.session:set_profile(action.arg) self:set_feedback("success", "Profile", "Switched to " .. action.arg)
	elseif n == "settings.live" then self:toggle_live()
	elseif n == "settings.reset" then self.session:reset() self.selected_path = nil self.static_result = nil self.report_text = nil
		self:set_feedback("success", "Reset", "Session data cleared from memory.")
	elseif n == "ui.minimize" then
		self.minimized = true
		self.ui_transition = true
	elseif n == "ui.restore" then
		self.minimized = false
		self.ui_transition = true
	elseif n == "ui.close" then
		self:destroy()
		return
	end
	self:render()
end

-- 0.6.1 scan lifecycle:
--   * progress callback is MEANINGFUL (visited count rendered into the top bar between batches --
--     possible because session.full_scan now yields cooperatively instead of the 0.6.0 no-op yield);
--   * CANCEL is wired: the top bar shows a Cancel button while busy; the session stops at the next
--     batch boundary and the PARTIAL/CANCELLED status is surfaced honestly here;
--   * live observations buffered during the scan are drained once, afterwards.
function A:do_scan()
	if self.busy then return end
	self.busy = true
	self.scan_progress = nil
	self:render()
	local ok, res = self.session:full_scan({
		progress = function(stage, done, total)
			self.scan_progress = { stage = stage, done = done, total = total }
			self:render()
		end,
	})
	self.busy = false
	self.scan_progress = nil
	pcall(function() self.session:drain_live() end)
	if not ok then
		self:set_feedback("error", "Scan failed", tostring(res))
	elseif res.status == "cancelled" then
		self:set_feedback("warning", "Scan CANCELLED",
			string.format("partial results kept: %d object(s) observed, %d candidate(s)", res.observed, res.findings))
	elseif res.status == "partial" then
		self:set_feedback("warning", "Scan PARTIAL",
			string.format("object cap reached: %d object(s) observed, %d candidate(s)", res.observed, res.findings))
	else
		self:set_feedback("success", "Scan completed",
			string.format("%d object(s) observed, %d candidate(s), %d stale", res.observed, res.findings, res.stale or 0))
	end
	self:render()
end

function A:cancel_scan()
	if not self.busy then return end
	self.session:request_cancel()
	self:set_feedback("warning", "Cancelling", "The scan stops at the next batch boundary; partial results are kept.")
	self:render()
end

-- heartbeat entry point (RunService.Heartbeat wired by the bootstrap tail): drains passive live
-- observations on a bounded schedule and reports whether the UI should re-render.
function A:tick()
	if self.busy then return false end
	local ok, changed = pcall(function() return self.session:tick() end)
	return ok and changed == true
end

function A:toggle_live()
	if self.session:live_info().running then
		self.session:stop_live()
	else
		local ok = self.session:start_live()
		if not ok then self:set_feedback("warning", "Unavailable", "Live observation is not available in this environment.") end
	end
end

function A:do_snapshot()
	local snap = self.session:snapshot()
	self.session.snapshots[#self.session.snapshots + 1] = snap
	while #self.session.snapshots > 10 do table.remove(self.session.snapshots, 1) end
	self:set_feedback("success", "Snapshot", tostring(snap.remote_count) .. " remote(s) captured in memory.")
end

-- 0.6.1: Save LATEST persists the most recent STORED snapshot (session:save_snapshot() now does
-- exactly that; 0.6.0 silently captured a brand-new snapshot here, so the saved file could differ
-- from what the operator saw as "latest").
function A:do_save_snapshot()
	if #self.session.snapshots == 0 then
		self:set_feedback("warning", "Nothing to save", "Create a snapshot first.")
		return
	end
	local ok, res = self.session:save_snapshot()
	if ok then
		self:set_feedback("success", "Saved", "Latest in-memory snapshot written to " .. res)
	else
		self:set_feedback("warning", "Not saved", res)
	end
end

-- 0.6.1: compare TWO ACTUAL SNAPSHOTS (selected previous vs latest). 0.6.0 called
-- self.session:compare(...) -- a method that DID NOT EXIST -- so the button errored out; when it
-- accidentally ran through other paths it compared against a freshly assumed inventory snapshot.
function A:do_compare()
	local snaps = self.session.snapshots
	if #snaps < 2 then
		self:set_feedback("warning", "Need two snapshots", "Create at least two snapshots; comparison runs previous vs latest.")
		return
	end
	local idx = self.compare_prev_idx or (#snaps - 1)
	if idx < 1 or idx > #snaps - 1 then idx = #snaps - 1 end
	self.compare_prev_idx = idx
	local ok, res = self.session:compare(snaps[idx], snaps[#snaps])
	if ok then
		self.compare_result = res
		self:set_feedback("success", "Compared",
			string.format("snapshot %d vs latest (%d): +%d added, -%d removed, ~%d changed",
				idx, #snaps, res.added_count, res.removed_count, res.changed_count))
	else
		self:set_feedback("error", "Compare failed", tostring(res))
	end
end

function A:do_static_scan()
	if #util.trim(tostring(self.static_source)) == 0 then
		self:set_feedback("warning", "Nothing to analyze", "Paste source first. Nothing was analyzed.")
		return
	end
	local ok, res = pcall(self.static.analyze, self.static_source, self.static_source_name)
	if not ok then
		self:set_feedback("error", "Analysis failed", tostring(res))
		return
	end
	self.static_result = res
	self:set_feedback("success", "Static analysis", res.summary.total .. " finding(s); status " .. res.status .. ".")
end

function A:do_report()
	local report_mod = require("src.report")
	self.report_text = report_mod.generate_combined(self.session, self.static_result)
	self:set_feedback("success", "Generated", "The full plaintext report is ready below.")
end

function A:do_copy(text, what)
	if not text or #text == 0 then
		self:set_feedback("warning", "Nothing to copy", "Generate it first.")
		return
	end
	if not self.caps.setclipboard then
		self:set_feedback("warning", "Manual copy", "No clipboard function — the report is readable in the panel; copy it manually.")
		return
	end
	local ok, err = pcall(self.caps.setclipboard, text)
	if ok then
		self:set_feedback("success", "Copied", "The " .. (what or "content") .. " was copied (" .. #text .. " characters).")
	else
		self:set_feedback("warning", "Copy failed", util.err_message(err) .. " Use the manual-copy fallback.")
	end
end

function A:do_export()
	if not self.report_text then return end
	local ok, res = require("src.export").export_txt(self.report_text, self.caps, "ShadowScanAudit_" .. (self.session.last_scan and "runtime" or "report") .. ".txt")
	if ok then self:set_feedback("success", "Exported", "Wrote " .. res) else self:set_feedback("warning", "Export unavailable", res) end
end

function A:destroy(from_owner)
	if self.destroyed then return end
	self.destroyed = true
	if self.renderer then self.renderer:destroy() self.renderer = nil end
	if not from_owner and type(self.deps.on_close) == "function" then
		pcall(self.deps.on_close)
	end
end

return A
end
__factories["src.classify"] = function(require)
-- Smart remote classification: buckets remotes into coarse FUNCTIONAL FAMILIES from name / parent-name tokens.
-- A family is a REVIEW AID, not a fact: the client cannot see what a remote actually does. Every classification
-- carries its basis (which token matched where) and a confidence that is "low" unless two independent sources agree.
-- Pure function; deterministic; no network, no remotes.
local util = require("src.util")

local C = {}

-- family -> (exact tokens, prefixes). Ordered: the FIRST family that matches wins (more specific first).
-- 0.4.0 set per the spec: Economy, Currency, Shop, Inventory, Rewards, Progression, Combat, Movement,
-- Teleportation, Admin, Permission, Trading, Social (+ Unknown). Every match records its basis.
C.FAMILIES = {
	{ key = "admin", label = "Admin", words = util.set({ "admin", "admins", "mod", "mods", "moderator", "ban", "bans", "kick", "staff", "owner", "sudo", "command", "commands", "cmd", "debug", "godmode" }), prefixes = { "administr", "moderat" } },
	{ key = "permission", label = "Permission", words = util.set({ "permission", "permissions", "whitelist", "blacklist", "rank", "privilege", "access", "auth", "authorize" }), prefixes = { "authoriz", "permiss" } },
	{ key = "teleportation", label = "Teleportation", words = util.set({ "teleport", "tp", "warp", "waypoint" }), prefixes = { "telepor" } },
	{ key = "movement", label = "Movement", words = util.set({ "walk", "walkspeed", "run", "sprint", "jump", "dash", "move", "movement", "speed", "spawn", "respawn", "mount", "ride", "crawl", "swim" }), prefixes = {} },
	{ key = "trading", label = "Trading", words = util.set({ "trade", "trades", "trading", "offer", "offers", "exchange", "swap", "gift" }), prefixes = {} },
	{ key = "shop", label = "Shop", words = util.set({ "shop", "store", "buy", "sell", "purchase", "price", "cart", "checkout", "market", "vendor", "order" }), prefixes = { "purchas" } },
	{ key = "economy", label = "Economy", words = util.set({ "money", "cash", "wallet", "bank", "balance", "deposit", "withdraw", "robux", "pay", "payment", "refund", "income", "salary", "tax" }), prefixes = { "currenc" } },
	{ key = "currency", label = "Currency", words = util.set({ "coin", "coins", "gold", "gems", "gem", "diamond", "diamonds", "credits", "credit", "points", "token", "tokens", "give", "grant", "coins" }), prefixes = {} },
	{ key = "inventory", label = "Inventory", words = util.set({ "inventory", "equip", "unequip", "item", "items", "drop", "pickup", "loot", "pet", "pets", "tool", "tools", "craft", "backpack", "slot", "stash", "storage" }), prefixes = { "inventor", "equipment" } },
	{ key = "rewards", label = "Rewards", words = util.set({ "reward", "rewards", "claim", "daily", "bonus", "freebie", "redeem", "prize", "wheel" }), prefixes = {} },
	{ key = "progression", label = "Progression", words = util.set({ "level", "levels", "xp", "exp", "experience", "quest", "quests", "rebirth", "unlock", "achievement", "prestige", "mission", "checkpoint", "stage", "progress", "save", "load", "data", "settings", "config" }), prefixes = { "achievem", "progress" } },
	{ key = "combat", label = "Combat", words = util.set({ "damage", "hit", "attack", "shoot", "weapon", "heal", "kill", "health", "explode", "projectile", "ability", "cast", "stun", "revive", "swing", "respawnplayer" }), prefixes = { "damag", "weapon" } },
	{ key = "social", label = "Social", words = util.set({ "chat", "message", "messages", "whisper", "friend", "friends", "party", "team", "emote", "emoji", "bubble", "mention", "join", "leave", "serverhop" }), prefixes = {} },
}

C.UNKNOWN = { key = "unknown", label = "Unclassified" }

-- classify(obs) -> { family, label, confidence, basis } | nil (only remotes classify)
function C.classify(obs)
	if not ({ RemoteEvent = true, RemoteFunction = true, UnreliableRemoteEvent = true })[obs.class_name] then return nil end
	local hits = {}
	-- source 1: the remote's own name (a default class name carries no information)
	if obs.name ~= obs.class_name then
		local fam = C.match(obs.name)
		if fam then hits[#hits + 1] = { source = "name", token = fam.token, family = fam.family } end
	end
	-- source 2: the parent container's name (nested containers only - a root service name like
	-- "ReplicatedStorage" carries no developer intent and must not classify anything)
	local parent_name = obs.parent_path and util.last_segment(obs.parent_path) or nil
	if parent_name and parent_name ~= obs.name and (obs.parent_path:find(".", 1, true)) then
		local fam = C.match(parent_name)
		if fam then hits[#hits + 1] = { source = "parent", token = fam.token, family = fam.family } end
	end
	if #hits == 0 then return nil end
	local primary = hits[1].family
	local agree = false
	for _, h in ipairs(hits) do
		if h.family == primary and h ~= hits[1] then agree = true end
	end
	return {
		family = primary,
		label = C.label(primary),
		confidence = agree and "medium" or "low", -- never "high": the client cannot observe behaviour
		basis = hits,
	}
end

function C.match(text)
	local toks = util.tokenize(tostring(text))
	for _, fam in ipairs(C.FAMILIES) do
		local tok = util.match_tokens(toks, fam.words, fam.prefixes)
		if tok then return { family = fam.key, token = tok } end
	end
	return nil
end

function C.label(key)
	for _, fam in ipairs(C.FAMILIES) do
		if fam.key == key then return fam.label end
	end
	return C.UNKNOWN.label
end

-- families of the given findings (in analysis order), for the Explorer's summary
function C.tally(findings)
	local order, counts = {}, {}
	for _, f in ipairs(findings) do
		local fam = f.classification and f.classification.family or C.UNKNOWN.key
		if not counts[fam] then counts[fam] = { family = fam, label = f.classification and f.classification.label or C.UNKNOWN.label, count = 0, top_risk = 0 } end
		counts[fam].count += 1
		local score = f.risk and f.risk.score or 0
		if score > counts[fam].top_risk then counts[fam].top_risk = score end
	end
	for _, c in pairs(counts) do order[#order + 1] = c end
	table.sort(order, function(a, b)
		if a.count ~= b.count then return a.count > b.count end
		return a.family < b.family
	end)
	return order
end

return C
end
