__factories["src.export"] = function(require)
-- Clipboard + TXT export with capability awareness. Every function detects, validates return types and
-- reports honestly: an export that cannot happen NEVER claims success - it returns a manual fallback path.
local config = require("src.config")
local util = require("src.util")

local X = {}

-- copy(text, caps) -> ok, how|reason
-- "how" is "clipboard" on success; on failure "reason" explains and the caller offers manual copy.
function X.copy(text, caps)
	if type(text) ~= "string" or #text == 0 then
		return false, "there is nothing to copy yet"
	end
	if not caps or not caps.setclipboard then
		return false, "this environment exposes no clipboard function - use the manual copy fallback"
	end
	local ok, err = pcall(caps.setclipboard, text)
	if not ok then
		return false, "the clipboard call failed: " .. util.clean_text(util.err_message(err), 120)
	end
	-- validate the effect where the executor allows verification; otherwise trust the pcall
	return true, "clipboard"
end

-- export_txt(text, caps, base_name) -> ok, path|reason
function X.export_txt(text, caps, base_name)
	if type(text) ~= "string" or #text == 0 then
		return false, "there is no report to export yet"
	end
	if not caps or not caps.writefile then
		return false, "this environment exposes no writefile function - use the manual copy fallback"
	end
	local name = tostring(base_name or "report")
	name = string.match(name, "([%w_%-%.]+)$") or "report.txt" -- strip any path parts
	if not string.match(name, "%.txt$") then name = name .. ".txt" end
	local dir = config.OUT_DIR
	if caps.makefolder then
		local exists = true
		if caps.isfolder then
			local ok_is, is = pcall(caps.isfolder, dir)
			exists = ok_is and is == true
		end
		if not exists then
			pcall(caps.makefolder, dir)
		end
	end
	local path = dir .. "/" .. name
	local ok, err = pcall(caps.writefile, path, text)
	if not ok then
		return false, "the write failed: " .. util.clean_text(util.err_message(err), 120)
	end
	-- type-validate what we can: some executors return values from writefile; a silent success is fine
	return true, path
end

-- manual_copy_text(text, max_chars) -> a displayable chunk for the manual-copy fallback
function X.manual_copy_text(text, max_chars)
	if type(text) ~= "string" or #text == 0 then return "" end
	local cap = max_chars or 4000
	if #text <= cap then return text end
	return string.sub(text, 1, cap) .. "\n\n[" .. (#text - cap) .. " more characters - use Export TXT for the full report]"
end

return X
end
__factories["src.graph"] = function(require)
-- Remote relationship graph, derived ONLY from replicated structure (factual relations, no guessing):
--   child_of    : a remote lives inside a container (parent_path)
--   sibling_of  : two remotes share the same parent_path
--   co_named    : the same remote name appears at several paths
-- The graph is a bounded, data-level adjacency structure (never rendered eagerly in the GUI; pages page through it).
local util = require("src.util")

local G = {}

G.MAX_NODES = 400
G.MAX_EDGES = 1200
G.MAX_SIBLING_FAN = 24 -- per parent: cap sibling edges so one huge folder cannot dominate the graph

-- build(observations) -> { nodes, edges, stats }
function G.build(observations)
	local remotes, containers, names = {}, {}, {}
	for _, o in ipairs(observations) do
		local is_remote = o.class_name == "RemoteEvent" or o.class_name == "RemoteFunction" or o.class_name == "UnreliableRemoteEvent"
		if is_remote then
			remotes[#remotes + 1] = o
			local pp = o.parent_path or "?"
			if not containers[pp] then containers[pp] = { path = pp, name = util.last_segment(pp), remotes = {} } end
			local c = containers[pp]
			c.remotes[#c.remotes + 1] = o
			local nk = o.class_name .. "|" .. o.name
			names[nk] = (names[nk] or 0) + 1
		end
	end

	local nodes, edges = {}, {}
	local by_id = {}
	local truncated = false

	local function node(id, kind, class, name, path)
		if by_id[id] then return by_id[id] end
		if #nodes >= G.MAX_NODES then truncated = true return nil end
		local n = { id = id, kind = kind, class = class, name = name, path = path }
		by_id[id] = n
		nodes[#nodes + 1] = n
		return n
	end

	local function edge(kind, from, to, evidence)
		if #edges >= G.MAX_EDGES then truncated = true return end
		edges[#edges + 1] = { kind = kind, from = from, to = to, evidence = evidence }
	end

	local container_ids = {}
	for _, pp in ipairs(util.sorted_keys(containers)) do
		local c = containers[pp]
		if #c.remotes > 0 then
			local cid = "C:" .. pp
			local cn = node(cid, "container", "Container", c.name, pp)
			if cn then
				container_ids[pp] = cid
			else
				break -- node budget exhausted
			end
		end
	end

	for _, o in ipairs(remotes) do
		local rid = "R:" .. o.path
		local rn = node(rid, "remote", o.class_name, o.name, o.path)
		if not rn then break end
		local cid = container_ids[o.parent_path or "?"]
		if cid then edge("child_of", rid, cid, "replicated structure") end
	end

	-- sibling_of: remotes sharing a container (bounded per container, deterministic order)
	for _, pp in ipairs(util.sorted_keys(containers)) do
		local c = containers[pp]
		local ids = {}
		for _, o in ipairs(c.remotes) do
			if by_id["R:" .. o.path] then ids[#ids + 1] = "R:" .. o.path end
		end
		table.sort(ids)
		for i = 1, math.min(#ids - 1, G.MAX_SIBLING_FAN) do
			for j = i + 1, math.min(#ids, G.MAX_SIBLING_FAN + 1) do
				if i < j then edge("sibling_of", ids[i], ids[j], "same container: " .. pp) end
				if #edges >= G.MAX_EDGES then break end
			end
			if #edges >= G.MAX_EDGES then break end
		end
	end

	-- co_named: same class+name at several paths (factual duplicate), one edge per extra occurrence
	for _, nk in ipairs(util.sorted_keys(names)) do
		if names[nk] > 1 then
			local cls, nm = nk:match("^([^|]+)|(.*)$")
			local group = {}
			for _, o in ipairs(remotes) do
				if o.class_name == cls and o.name == nm and by_id["R:" .. o.path] then group[#group + 1] = "R:" .. o.path end
			end
			table.sort(group)
			for i = 2, #group do
				edge("co_named", group[1], group[i], string.format("%d remotes share the name '%s'", names[nk], nm))
				if #edges >= G.MAX_EDGES then break end
			end
			if #edges >= G.MAX_EDGES then break end
		end
	end

	return {
		nodes = nodes, edges = edges,
		stats = { remotes = #remotes, containers = util.count(containers), nodes = #nodes, edges = #edges, truncated = truncated },
	}
end

-- containers sorted by remote count (desc), for the Explorer's bounded summary
function G.container_summary(graph, cap)
	local out = {}
	local seen = {}
	for _, e in ipairs(graph.edges) do
		if e.kind == "child_of" then
			seen[e.to] = (seen[e.to] or 0) + 1
		end
	end
	for _, n in ipairs(graph.nodes) do
		if n.kind == "container" then
			out[#out + 1] = { path = n.path, name = n.name, remotes = seen[n.id] or 0 }
		end
	end
	table.sort(out, function(a, b)
		if a.remotes ~= b.remotes then return a.remotes > b.remotes end
		return a.path < b.path
	end)
	if cap and #out > cap then
		local trimmed = {}
		for i = 1, cap do trimmed[i] = out[i] end
		return trimmed, #out
	end
	return out, #out
end

-- Compact report listing: top containers by remote count with (capped) member remote paths.
function G.listing(graph, cap_containers, cap_remotes)
	local path_of = {}
	for _, n in ipairs(graph.nodes) do path_of[n.id] = n.path end
	local per, counts = {}, {}
	for _, e in ipairs(graph.edges) do
		if e.kind == "child_of" then
			counts[e.to] = (counts[e.to] or 0) + 1
			per[e.to] = per[e.to] or {}
			if #per[e.to] < cap_remotes then per[e.to][#per[e.to] + 1] = path_of[e.from] or e.from end
		end
	end
	local out = {}
	for _, n in ipairs(graph.nodes) do
		if n.kind == "container" then
