-- Minimal JSON decoder for test fixtures (pure Luau; no external deps).
local J = {}
function J.decode(s)
	local pos = 1
	local function skip()
		while pos <= #s and s:sub(pos, pos):match("%s") do pos += 1 end
	end
	local parse_value
	local function parse_string()
		local out = {}
		pos += 1
		while pos <= #s do
			local c = s:sub(pos, pos)
			if c == '"' then pos += 1 return table.concat(out) end
			if c == "\\" then
				pos += 1
				local e = s:sub(pos, pos)
				local map = { n = "\n", t = "\t", r = "\r" }
				out[#out + 1] = map[e] or e
				pos += 1
			else
				out[#out + 1] = c
				pos += 1
			end
		end
		error("unterminated string")
	end
	local function parse_object()
		local o = {}
		pos += 1
		skip()
		if s:sub(pos, pos) == "}" then pos += 1 return o end
		while true do
			skip()
			local k = parse_string()
			skip()
			assert(s:sub(pos, pos) == ":")
			pos += 1
			o[k] = parse_value()
			skip()
			local c = s:sub(pos, pos)
			pos += 1
			if c == "}" then return o end
			assert(c == ",")
		end
	end
	local function parse_array()
		local a = {}
		pos += 1
		skip()
		if s:sub(pos, pos) == "]" then pos += 1 return a end
		while true do
			a[#a + 1] = parse_value()
			skip()
			local c = s:sub(pos, pos)
			pos += 1
			if c == "]" then return a end
			assert(c == ",")
		end
	end
	parse_value = function()
		skip()
		local c = s:sub(pos, pos)
		if c == '"' then return parse_string() end
		if c == "{" then return parse_object() end
		if c == "[" then return parse_array() end
		if s:sub(pos, pos + 3) == "true" then pos += 4 return true end
		if s:sub(pos, pos + 4) == "false" then pos += 5 return false end
		if s:sub(pos, pos + 3) == "null" then pos += 4 return nil end
		local start = pos
		while pos <= #s and s:sub(pos, pos):match("[%-%d%.eE+]") do pos += 1 end
		return tonumber(s:sub(start, pos - 1)) or error("bad json at " .. pos)
	end
	return parse_value()
end
return J
end
