function M:analyze(source, name) return self:analyze_source(source, name) end

function M:analyze_source(source, name)
	return static_engine.analyze(source, { name = name })
end

function M:static_report_text(source, name)
	local result = self:analyze_source(source, name)
	return report_mod.generate_static(result), result
end

-- combined report (runtime + optional static)
function M:report_text(static_result)
	return report_mod.generate_combined(self.session, static_result)
end

function M:copy_report(text)
	if not text or #text == 0 then return false, "nothing to copy" end
	if not self.caps.setclipboard then return false, "no clipboard function - use the manual-copy fallback" end
	local ok, err = pcall(self.caps.setclipboard, text)
	if not ok then return false, "clipboard call failed: " .. util.err_message(err) end
	return true, "clipboard"
end

function M:export_report(text, base_name)
	if not text or #text == 0 then return false, "nothing to export" end
	if not self.caps.writefile then return false, "no writefile function - use the manual-copy fallback" end
	local name = tostring(base_name or "ShadowScanAudit.txt")
	name = string.match(name, "([%w_%-%.]+)$") or "ShadowScanAudit.txt"
	if not string.match(name, "%.txt$") then name = name .. ".txt" end
	local dir = "ShadowScan/out"
	if self.caps.makefolder then pcall(self.caps.makefolder, dir) end
	local ok, err = pcall(self.caps.writefile, dir .. "/" .. name, text)
	if not ok then return false, "write failed: " .. util.err_message(err) end
	return true, dir .. "/" .. name
end

-- 0.6.1: describe() can NEVER error, even on a half-initialized instance or when called through a
-- loader that ignores the returned values (0.6.0 crashed here when self.caps was nil, which is
-- exactly what happens if the module table -- not an instance -- is described).
function M:describe()
	local ok, caps_text = pcall(util.describe_caps, self.caps or {}, self.executor_name)
	if not ok or type(caps_text) ~= "string" then caps_text = "executor=unknown clipboard=NO writefile=NO" end
	return "ShadowScan " .. config.VERSION .. " (" .. config.EDITION .. ") - " .. caps_text
end

-- heartbeat entry point (wired by the bootstrap in GUI mode): drains passive live observations
-- into the session and reports whether anything changed (the caller re-renders on true).
function M:tick()
	local changed = false
	if self.session and self.session.tick then changed = self.session:tick() end
	return changed == true
end

function M:destroy(from_app_close)
	if self.destroyed then return end
	self.destroyed = true
	if self.app then self.app:destroy(true) self.app = nil end
	if self.session then self.session:stop_live() end
end

return M
end
