local config = require("src.config")

local R = {}

local RULE = string.rep("-", 30)
local BAR = string.rep("=", 50)

local LIMITATIONS = {
	"- Client-visible inventory only: StreamingEnabled and replication can hide objects from any client.",
	"- Static analysis reads text only. It cannot prove how code behaves at runtime.",
	"- A pattern being present does not prove malicious intent; several rules match normal development code.",
	"- A disappearance between snapshots does not prove deletion (replication or streaming).",
	"- Names, metadata and structure are hints. Server-side validation is invisible from the client.",
	"- The scanner never fires remotes, never modifies game state, never reads server-only instances.",
