	"- Encoded or network-fetched content is visible only as an indicator; it is not decoded or downloaded.",
}

local function rand_hex(n)
	local out = {}
	for i = 1, n do out[i] = string.format("%02x", math.random(0, 255)) end
	return table.concat(out)
end

local function severity_counts(findings)
	local counts = { CRITICAL = 0, HIGH = 0, MEDIUM = 0, LOW = 0, INFORMATIONAL = 0, UNCLASSIFIED = 0 }
	for _, finding in ipairs(findings or {}) do
		local key = string.upper(tostring(finding.severity or "UNCLASSIFIED"))
		if counts[key] ~= nil then counts[key] += 1 else counts.UNCLASSIFIED += 1 end
	end
