			push(out, "Path: " .. tostring(f.object_path))
			push(out, "Severity: " .. string.upper(tostring(f.severity or "UNCLASSIFIED")))
			push(out, "Candidate Priority: " .. tostring(f.risk and f.risk.priority or 0) .. "/100")
			push(out, "Evidence Confidence: " .. tostring(f.risk and f.risk.evidence_confidence or f.confidence))
			push(out, "Verification Status: " .. tostring(f.risk and f.risk.verification_status or "unverified"))
			push(out, "", "Evidence:")
			for _, e in ipairs(f.evidence or {}) do
				push(out, "  - [" .. tostring(e.kind) .. "] " .. truncate(tostring(e.detail or ""), 200))
			end
			push(out, "", "Explanation:", "  " .. tostring(f.rationale), "")
			push(out, "Recommended next step:", "  " .. (f.suggested_tests and f.suggested_tests[1]
				and f.suggested_tests[1].note or "Review with the developer; a name or location alone proves nothing."), "")
		end
	end

	if session.graph then
		push(out, RULE, "RELATIONSHIP SUMMARY", RULE, "")
		push(out, string.format("%d remote(s) across %d container(s); graph nodes %d, edges %d%s",
			session.graph.stats.remotes, session.graph.stats.containers, session.graph.stats.nodes,
			session.graph.stats.edges, session.graph.stats.truncated and " (truncated)" or ""))
		local containers = {}
		for _, n in ipairs(session.graph.nodes) do
			if n.kind == "container" then containers[#containers + 1] = n end
		end
		table.sort(containers, function(a, b) return a.path < b.path end)
		for i, c in ipairs(containers) do
			if i > 20 then push(out, "  (remaining containers omitted)"); break end
			push(out, "  " .. c.path)
		end
		push(out, "")
	end

	if #session.snapshots > 0 then
		local snap = session.snapshots[#session.snapshots]
		push(out, RULE, "SESSION SNAPSHOT", RULE, "")
		push(out, "Latest snapshot: " .. tostring(snap.created_utc) .. " (" .. tostring(snap.remote_count) .. " remote(s))")
		push(out, "")
	end

