		push(out, RULE, "STATIC ANALYSIS", RULE, "")
		push(out, "Status: " .. static_result.status)
		push(out, "Source Name: " .. tostring(static_result.source_name))
		push(out, "Lines Analyzed: " .. tostring(static_result.lines_analyzed) .. " of " .. tostring(static_result.lines_total))
		push(out, "Rules Evaluated: " .. tostring(static_result.rules_evaluated))
		push(out, "Findings: " .. tostring(static_result.summary.total))
		if static_result.partial_reason then push(out, "Partial reason: " .. static_result.partial_reason) end
		push(out, "")
		for i, f in ipairs(static_result.findings) do
			if i > 100 then push(out, "(remaining static findings omitted - report is bounded)"); break end
			push(out, "[S-" .. string.format("%03d", i) .. "] " .. f.title, "")
