		end,
		basis = function(f)
			for _, e in ipairs(f.evidence) do
				if e.kind == "observed_property" and e.rule_id ~= "R-EXPOSE-VALUE" then return e.rule_id end
			end
			return ""
		end },
	{ id = "F-SECRET-SHAPED", label = "Secret-shaped replicated value", points = 30, max = 30,
		condition = function(f)
			for _, e in ipairs(f.evidence) do
				if e.kind == "observed_property" and e.rule_id == "R-EXPOSE-VALUE" then return true end
			end
			return false
		end,
		basis = function() return "a replicated value matches a credential-shaped pattern" end },
	{ id = "F-DUPLICATE-GENERIC", label = "Duplicate or generic naming", points = 5, max = 5, weak = true,
		condition = function(f)
			for _, e in ipairs(f.evidence) do
				if e.rule_id == "R-UNUSUAL-DUPLICATE" or e.rule_id == "R-UNUSUAL-GENERIC" then return true end
			end
			return false
		end,
		basis = function(f)
			for _, e in ipairs(f.evidence) do
				if e.rule_id == "R-UNUSUAL-DUPLICATE" or e.rule_id == "R-UNUSUAL-GENERIC" then return e.rule_id end
			end
			return ""
		end },
	{ id = "F-OUTSIDE-REPLICATEDSTORAGE", label = "Remote outside ReplicatedStorage", points = 5, max = 5, weak = true,
		condition = function(f) return string.sub(f.object_path or "", 1, 18) ~= "ReplicatedStorage." end,
		basis = function(f) return "path " .. tostring(f.object_path) .. " is not under ReplicatedStorage" end },
	{ id = "F-REMOTE-FUNCTION", label = "RemoteFunction (yielding, returns values)", points = 5, max = 5, weak = true,
		condition = function(f) return f.object_class == "RemoteFunction" end,
		basis = function() return "RemoteFunction" end },
