		hits[#hits + 1] = {
			rule_id = "R-UNUSUAL-GENERIC", category = "Unusual or undocumented remote surfaces", weak = true, severity = "informational", confidence = "low",
			kind = "structure", evidence = string.format("Remote uses a generic default-style name '%s'", obs.name),
			rationale = "Generic names make a remote's purpose undocumented and easy to overlook during review.",
			unknowns = { "What the remote does and who owns it" }, tests = TEST_SETS.manual,
		}
