			rule_id = "R-UNUSUAL-RANDOM", category = "Unusual or undocumented remote surfaces", weak = true, severity = "informational", confidence = "low",
			kind = "structure", evidence = "Remote name looks like a hash/GUID (" .. #obs.name .. " hex characters)",
			rationale = "Opaque names can indicate obfuscation or generated remotes that are not documented.",
			unknowns = { "Why the name is opaque", "What the remote does" }, tests = TEST_SETS.manual,
