		hits[#hits + 1] = {
			rule_id = "R-UNUSUAL-DUPLICATE", category = "Unusual or undocumented remote surfaces", weak = true, severity = "informational", confidence = "low",
			kind = "structure", evidence = string.format("%d remotes of class %s share the name '%s'", n, obs.class_name, obs.name),
			rationale = "Many identically named remotes make it hard to know which handler serves which caller.",
			unknowns = { "Which handler each duplicate maps to" }, tests = TEST_SETS.manual,
