end

-- All hits for one observation. `ctx.name_counts` is built by the analyzer.
function R.evaluate(obs, ctx)
	local hits = {}
	for _, list in ipairs({ name_hint_hits(obs, ctx), interaction_hits(obs), remote_structure_hits(obs, ctx), exposure_hits(obs) }) do
		for _, h in ipairs(list) do hits[#hits + 1] = h end
	end
	return hits
end

