end
__factories["src.secrets"] = function(require)
-- Secret detection shared by the passive scanner and the report builder.
-- The Python side (reporting/redact.py) keeps an equivalent list; tests/fixtures/secret_samples.json
-- is checked against BOTH implementations so the lists cannot silently drift apart.
local M = {}

M.PATTERNS = {
	{ kind = "age_private_key", pattern = "AGE%-SECRET%-KEY%-1[%u%d]+" },
	{ kind = "roblosecurity_cookie", pattern = "_|WARNING:%-DO%-NOT%-SHARE%-THIS" },
	{ kind = "roblosecurity_name", pattern = "%.ROBLOSECURITY" },
	{ kind = "private_key_block", pattern = "%-%-%-%-%-BEGIN [%u ]*PRIVATE KEY%-%-%-%-%-" },
	{ kind = "bearer_token", pattern = "[Bb]earer%s+[%w%._%-]+%.[%w%._%-]+" },
	{ kind = "discord_webhook", pattern = "discord[app]*%.com/api/webhooks/%d+/[%w_%-]+" },
	{ kind = "pairing_token", pattern = "ssp_[%w_%-]+" },
	{ kind = "aws_access_key", pattern = "AKIA[%u%d]+" },
}

-- Returns kind of first pattern found, or nil.
function M.find(s)
	if type(s) ~= "string" then return nil end
	for _, p in ipairs(M.PATTERNS) do
		local a, b = string.find(s, p.pattern)
		if a then
			-- pairing_token / aws need minimum length to avoid flagging innocuous words
			if p.kind == "pairing_token" and (b - a + 1) < 24 then
				-- too short, ignore
			elseif p.kind == "aws_access_key" and (b - a + 1) ~= 20 then
				-- not an AWS key shape
			else
				return p.kind
			end
		end
	end
	return nil
end

-- True when a *value* (not a name) looks like a credential: used for replicated StringValues.
-- The value itself is NEVER stored; only this boolean and the string length are kept.
function M.value_looks_secret(s)
	if type(s) ~= "string" then return false end
	if M.find(s) then return true end
	if #s >= 32 and not string.find(s, "%s") and string.match(s, "^[%w%+/=_%-%.]+$") then
		-- long unbroken token-like string (hex/base64/JWT-ish)
		return true
	end
	return false
end

-- Replace any secret-looking substring by [REDACTED]. Returns new string, number of replacements.
function M.redact(s)
	if type(s) ~= "string" then return s, 0 end
	local count = 0
	for _, p in ipairs(M.PATTERNS) do
		s = string.gsub(s, p.pattern, function(m)
			if p.kind == "pairing_token" and #m < 24 then return nil end
			if p.kind == "aws_access_key" and #m ~= 20 then return nil end
			count += 1
			return "[REDACTED]"
		end)
	end
	return s, count
end

-- Deep-redact every string value of a table tree. Returns a copy and the number of strings changed.
-- Metatables (json object/array/null markers) are preserved; the json.null sentinel is returned as-is.
function M.redact_deep(v)
	local changed = 0
	local function walk(x)
		local t = type(x)
		if t == "string" then
			local r, n = M.redact(x)
			if n > 0 then changed += 1 end
			return r
		elseif t == "table" then
			local mt = getmetatable(x)
			if mt and mt.__jsontype == "null" then return x end
			local out = {}
			for k, val in pairs(x) do out[k] = walk(val) end
			if mt then setmetatable(out, mt) end
			return out
		end
		return x
	end
	return walk(v), changed
end

return M
end
