-- The runtime session: owns the persistent inventory, classification, findings, relationship graph,
-- passive live observation and session snapshots. All state lives on the session object.
-- The scanner is strictly passive: it never fires or invokes remotes and never modifies game state.
--
-- 0.6.1 repairs:
--   * PROFILE_SETTINGS are actually applied to every scan (LOW IMPACT / BALANCED / FAST now differ).
--   * The default yield is a SAFE cooperative yield (task.wait/wait when present), never a silent no-op;
--     a scan in a GUI environment can no longer monopolize the execution thread between batches.
--   * Cancellation: request_cancel() is honoured by the running scan; the scan status becomes
--     "cancelled" and the PARTIAL results (already-observed objects) are kept and reportable.
--   * drain_live() folds live observations into the PERSISTENT inventory (not a dead scan_result
--     table), rebuilds findings AND graph, dedupes against the inventory, and reports overflow.
--   * save_snapshot() saves the LATEST STORED snapshot (what "Save Latest" claims), not a new capture.
--   * compare(previous, latest) compares two actual snapshots (explicit selection support in the UI).
--   * Stale objects are marked explicitly (stale=true, stale_since=<iso>) and never silently reported
--     as current; first_seen/last_seen metadata is preserved across scans.
local config = require("src.config")
local util = require("src.util")
local secrets = require("src.secrets")
local inventory = require("src.inventory")
local analyzer = require("src.analyzer")
local classify = require("src.classify")
local risk = require("src.risk")
local graph = require("src.graph")
local live_mod = require("src.live")
local snapshots = require("src.snapshots")

local S = {}
S.__index = S

function S.new(deps)
	deps = deps or {}
	local self = setmetatable({}, S)
	self.game = deps.game
	self.caps = deps.caps or {}
	self.profile = deps.profile or "balanced"
	self.deps = deps
	self.inventory = {}        -- identity path -> record (paths disambiguate duplicate sibling names)
	self.observations = {}     -- evidence records (0.4.x shape, feeding the analyzer)
	self.findings = {}
	self.graph = nil
	self.stats = { scans = 0, live_events = 0, duplicates = 0 }
	self.live = nil
	self.snapshots = {}        -- in-memory snapshot list (bounded)
	self.timings = {}
	self.last_scan = nil
	self.history = {}          -- bounded activity log
	self.cancel_requested = false
	self.last_scan_settings = nil   -- the PROFILE_SETTINGS actually applied to the last scan (observable)
	self.last_live_overflow = nil   -- last overflow report from drain_live (explicit, never silent)
	self.yield_fn = deps.yield or S.resolve_cooperative_yield()
	self.yield_misses = 0
	return self
end

function S:log(level, text)
	self.history[#self.history + 1] = { level = level or "info", text = tostring(text) }
	while #self.history > 200 do table.remove(self.history, 1) end
end

local PROFILE_SETTINGS = {
	low_impact = { batch_budget_ms = 1.5, batch_min = 8, batch_max = 128, progress_every = 4000 },
	balanced = { batch_budget_ms = 3, batch_min = 16, batch_max = 512, progress_every = 2000 },
	fast = { batch_budget_ms = 6, batch_min = 64, batch_max = 1024, progress_every = 1000 },
}
S.PROFILE_SETTINGS = PROFILE_SETTINGS

function S:set_profile(key)
	if not PROFILE_SETTINGS[key] then return false end
	self.profile = key
	self:log("info", "performance profile: " .. key)
	return true
end

-- Resolve a cooperative yield for the CURRENT environment. In a Roblox executor/runner this is
-- task.wait() (or legacy wait()); headless (Luau CLI, tests) none exists and scans stay batched but
-- synchronous -- exactly what the test suite injects its own yield for. Returns nil when unavailable;
-- the scan then still processes in bounded batches and records that no cooperative yield was possible.
function S.resolve_cooperative_yield()
	local ok_t, task_t = pcall(function() return task end)
	if ok_t and type(task_t) == "table" and type(task_t.wait) == "function" then
		return function() task_t.wait() end
	end
	local ok_w, wait_fn = pcall(function() return wait end)
	if ok_w and type(wait_fn) == "function" then
		return function() wait_fn() end
	end
	return nil
end

-- wrap any yield function so a broken/sandboxed wait can never abort a scan mid-batch
function S.make_safe_yield(fn, session)
	if type(fn) ~= "function" then return nil end
	return function()
