	end
	return snapshots.save(snap, self.caps)
end

function S:compare(previous, latest)
	if type(previous) ~= "table" then return false, "previous snapshot is missing or invalid" end
	if latest == nil then latest = self:snapshot() end
	return snapshots.compare_snaps(previous, latest)
end

function S:compare_snapshot_text(text) return snapshots.compare_text(text, self.inventory, self.game) end

-- heartbeat entry point (GUI tick): drain live observations, report whether anything changed
function S:tick()
	local added = self:drain_live()
	return added > 0 or self.last_live_overflow ~= nil
end

function S:reset()
	self.inventory = {}
	self.observations = {}
	self.findings = {}
	self.findings_by_path = nil
	self.graph = nil
	self.snapshots = {}
	self.last_scan = nil
	self.scan_stats = nil
	self.last_live_overflow = nil
	self.cancel_requested = false
	self:stop_live()
	if self.live then self.live.reset() end
	self:log("info", "session reset")
end

return S
end
