-- Session snapshots and comparison. A snapshot is a bounded, plaintext-safe fingerprint of the
-- client-visible remote surface. Comparison discloses matching confidence and never claims that a
-- disappearance proves deletion (replication/streaming).
--
-- 0.6.1 repairs:
--   * from_text(): legacy v1/v2 lines (class|name|path, no metadata) parse into COMPLETE records --
--     0.6.0 kept only the class name and crashed on the nil path during comparison.
--   * compare_snaps(previous, latest): compares TWO ACTUAL SNAPSHOTS (the Session page selects
--     previous/latest explicitly); compare(inventory, previous, game) keeps the 0.6.0 shape and now
--     delegates to the same diff core.
--   * create() discloses staleness: records flagged stale by the session are counted in the snapshot
--     header instead of being silently reported as current observations.
--   * renamed/reparented matches are consumed: a pair matched as RENAMED no longer also appears in
--     both ADDED and REMOVED (0.6.0 double-counted every match).
local util = require("src.util")

local S = {}

S.MAX_SNAPSHOTS = 10
S.MAX_DIFF_ITEMS = 50

-- create(inventory, game) -> snapshot table
function S.create(inventory, game)
	local remotes, counts = {}, {}
	local stale_count = 0
	for path, rec in pairs(inventory) do
		counts[rec.class_name] = (counts[rec.class_name] or 0) + 1
		if rec.class_name == "RemoteEvent" or rec.class_name == "RemoteFunction" or rec.class_name == "UnreliableRemoteEvent" then
			if rec.stale then stale_count += 1 end
			local mparts = {}
			for _, k in ipairs(util.sorted_keys(rec.metadata or {})) do
				local v = rec.metadata[k]
				if type(v) == "string" or type(v) == "number" or type(v) == "boolean" then
					mparts[#mparts + 1] = k .. "=" .. tostring(v)
				end
			end
			remotes[#remotes + 1] = {
				c = rec.class_name, n = rec.name, p = path,
				pp = rec.parent_path or "", m = table.concat(mparts, "|"),
				stale = rec.stale == true or nil,
			}
		end
	end
	table.sort(remotes, function(x, y)
		if x.p ~= y.p then return x.p < y.p end
		return x.c < y.c
	end)
