	if game then pcall(function() place_id = game.PlaceId end) end
	return {
		snapshot_version = 3, created_utc = os.date and os.date("!%Y-%m-%dT%H:%M:%SZ") or "unknown",
		place_id = place_id, remote_count = #remotes, stale_count = stale_count,
		counts = counts, remotes = remotes,
	}
