	local path = "ShadowScan/out/snapshot-" .. stamp .. ".txt"
	local ok, err = pcall(caps.writefile, path, S.to_text(snap))
	if not ok then return false, "write failed: " .. tostring(err) end
	return true, path
end

function S.to_text(snap)
	local out = {}
	out[#out + 1] = "SHADOWSCAN SESSION SNAPSHOT v" .. tostring(snap.snapshot_version)
	out[#out + 1] = "Created: " .. tostring(snap.created_utc)
	out[#out + 1] = "PlaceId: " .. tostring(snap.place_id)
	out[#out + 1] = "Remotes: " .. tostring(snap.remote_count)
	out[#out + 1] = "Stale: " .. tostring(snap.stale_count or 0)
	for _, r in ipairs(snap.remotes) do
