-- diff core: two sorted remote lists -> categorized differences with disclosed confidence.
-- Renamed/reparented matches are CONSUMED (removed from plain ADDED/REMOVED) so nothing is counted twice.
local function diff_remotes(previous, current)
	local prev_set, cur_set = {}, {}
	for _, r in ipairs(previous) do prev_set[r.c .. "|" .. r.p] = r end
	for _, r in ipairs(current) do cur_set[r.c .. "|" .. r.p] = r end

	local added, removed, changed = {}, {}, {}
	for k, r in pairs(cur_set) do
		local old = prev_set[k]
		if not old then
			added[#added + 1] = { class_name = r.c, name = r.n, path = r.p, confidence = "high", _row = r }
		elseif (old.m or "") ~= (r.m or "") then
			changed[#changed + 1] = { class_name = r.c, name = r.n, path = r.p,
				previous_metadata = old.m or "", current_metadata = r.m or "", confidence = "high" }
		end
	end
	for k, r in pairs(prev_set) do
		if not cur_set[k] then
			removed[#removed + 1] = { class_name = r.c, name = r.n, path = r.p, confidence = "high", _row = r }
		end
	end

	-- cross-session matching (disclosed confidence levels). A matched pair is CONSUMED: it no longer
	-- also appears in plain ADDED/REMOVED (0.6.0 double-counted every match).
	--   RENAMED:     same class + same parent path + same metadata, different name (medium)
	--   REPARENTED:  same class + same name + same metadata, different parent (medium)
	--   POSSIBLY_MOVED: always EMPTY in 0.6.1. 0.6.0 paired any same-class add/remove as a "move"
	--   (low confidence), which silently swallowed genuine additions and removals from the plain
	--   counts. A plain add/remove is the honest report; the note below already discloses that a
	--   disappearance does not prove deletion.
	local renamed, reparented = {}, {}
	local function take(list, i)
		list[i] = list[#list]
