	end
	local ri = 1
	while ri <= #removed do
		local rm = removed[ri]
		local matched = false
		for ai, ra in ipairs(added) do
			if rm.class_name == ra.class_name then
				local rp = string.match(rm.path, "^(.*)%.[^%.]+$") or ""
				local ap = string.match(ra.path, "^(.*)%.[^%.]+$") or ""
