					matched = true
				elseif rm.name == ra.name and (rm.m or "") == (ra.m or "") then
					reparented[#reparented + 1] = { class_name = rm.class_name, name = rm.name,
						from = rm.path, to = ra.path, confidence = "medium" }
					take(added, ai)
					matched = true
				end
				if matched then break end
			end
		end
