		ADDED = cap(added), REMOVED = cap(removed), METADATA_CHANGED = cap(changed),
		RENAMED = cap(renamed), REPARENTED = cap(reparented), POSSIBLY_MOVED = {},
		added_count = #added, removed_count = #removed, changed_count = #changed,
		renamed_count = #renamed, reparented_count = #reparented, moved_count = 0,
		previous_remote_count = #previous, current_remote_count = #current,
