-- compare two ACTUAL snapshots (0.6.1: the Session page selects previous/latest explicitly)
function S.compare_snaps(previous, latest)
	if type(previous) ~= "table" or type(previous.remotes) ~= "table" then
		return false, "the previous snapshot is not a valid ShadowScan session snapshot"
	end
	if type(latest) ~= "table" or type(latest.remotes) ~= "table" then
		return false, "the latest snapshot is not a valid ShadowScan session snapshot"
	end
	if previous.place_id ~= nil and latest.place_id ~= nil and previous.place_id ~= latest.place_id then
		return false, "the snapshots were taken in different places; comparison refused"
	end
	local diff = diff_remotes(previous.remotes, latest.remotes)
	diff.previous_created_utc = previous.created_utc
	diff.latest_created_utc = latest.created_utc
	return true, diff
end

-- compare(current_inventory, previous_snapshot, game) -> ok, diff | reason
-- (0.6.0 shape preserved for compatibility: current inventory is fingerprinted on the fly)
function S.compare(inventory, previous, game)
	if type(previous) ~= "table" or type(previous.remotes) ~= "table" then
		return false, "that snapshot is not a valid ShadowScan session snapshot"
	end
	local current = S.create(inventory, game)
	if previous.place_id and current.place_id and previous.place_id ~= current.place_id then
		return false, "snapshot was taken in a different place; comparison refused"
	end
	local diff = diff_remotes(previous.remotes, current.remotes)
	diff.previous_created_utc = previous.created_utc
	diff.latest_created_utc = current.created_utc
	diff.current_stale_count = current.stale_count or 0
	return true, diff
end

function S.compare_text(text, inventory, game)
	local prev, err = S.from_text(text)
	if not prev then return false, err end
	return S.compare(inventory, prev, game)
end

return S
end
__factories["src.static_engine"] = function(require)
-- The analysis engine: line-oriented scan of a Luau source string, then a correlation pass.
-- Bounded and cooperative: yields and progress callbacks between line batches; hard caps on lines,
-- findings and evidence. The engine NEVER executes the analyzed source and never touches the network.
--
-- analyze(source, opts) -> result
--   opts: { name = "source name", progress = fn(stage, lines_done, total_lines), yield = fn }
--   result = {
--     status = "completed" | "partial" | "empty",
--     source_name, scan_id, lines_total, lines_analyzed, rules_evaluated, truncated, partial_reason,
--     findings = { {id, rule_id, title, severity, confidence, line, evidence, explanation, impact,
--                  recommendation, category, correlated_by} ... },
--     summary = { counts = {CRITICAL=..HIGH=..MEDIUM=..LOW=..INFORMATIONAL=..}, total, overall_risk },
--   }
local config = require("src.config")
local util = require("src.util")
local rules = require("src.static_rules")

local E = {}

local SEV_RANK = { CRITICAL = 5, HIGH = 4, MEDIUM = 3, LOW = 2, INFORMATIONAL = 1 }

-- overall risk: driven by the WORST present severity, but honest about what that means
local function overall_risk(counts)
	if (counts.CRITICAL or 0) > 0 then
		return "CRITICAL - credential-access patterns present; review before running this code anywhere"
	end
	if (counts.HIGH or 0) > 0 then
		return "HIGH - strong suspicious indicators present; manual review required"
	end
	if (counts.MEDIUM or 0) > 0 then
		return "MEDIUM - potentially unsafe patterns present; verify the flagged behaviour is intended"
	end
	if (counts.LOW or 0) > 0 then
		return "LOW - minor observations; no strong indicators"
	end
	if (counts.INFORMATIONAL or 0) > 0 then
		return "INFORMATIONAL - normal patterns observed"
	end
	return "CLEAN - no known patterns matched (static analysis cannot prove runtime safety)"
end

-- comment handling: handles -- line comments and --[[ ]] block comments (false-positive control).
-- Returns the EFFECTIVE CODE TEXT for the line: code before a -- comment, or "" inside a block comment.
-- A line whose code part is empty contributes nothing to pattern matching; code before an inline
-- comment is still analyzed (e.g. "loadstring(x) -- note" keeps its code).
local function effective_code(line, in_block)
	local s = line
	if in_block then
		local close = string.find(s, "]]", 1, true)
		if not close then return "", true end
		in_block = false
		s = string.sub(s, close + 2)
	end
	local i = 1
	while i <= #s do
		local two = string.sub(s, i, i + 1)
		if two == "--" then
			local long = string.sub(s, i + 2, i + 3) == "[[" or string.sub(s, i + 2, i + 3) == "[=["
			if long then return "", true end
			return string.sub(s, 1, i - 1), in_block
		end
		i += 1
	end
	return s, in_block
end

-- split source into lines ONCE (no repeated parsing); capped
local function split_lines(source)
	local lines = {}
	local start = 1
	local n = 0
	local len = #source
	while start <= len do
		local nl = string.find(source, "\n", start, true)
		local stop = nl and (nl - 1) or len
		n += 1
		local raw = string.sub(source, start, stop)
		lines[n] = (#raw > config.MAX_LINE_LEN) and string.sub(raw, 1, config.MAX_LINE_LEN) or raw
		if n >= config.MAX_LINES then
			return lines, true
		end
		if not nl then break end
		start = nl + 1
	end
	if n == 0 and len > 0 then lines[1] = source; n = 1 end
	return lines, false
end

function E.analyze(source, opts)
	opts = opts or {}
	local result = {
		status = "completed", source_name = tostring(opts.name or "pasted source"),
		scan_id = util.rand_hex(8),
		lines_total = 0, lines_analyzed = 0, rules_evaluated = rules.count(),
		truncated = false, partial_reason = nil,
		findings = {}, summary = { counts = {}, total = 0, overall_risk = "CLEAN" },
		started_at = util.timestamp(),
	}

	if type(source) ~= "string" or #util.trim(source) == 0 then
		result.status = "empty"
		result.partial_reason = "No source was provided, so nothing was analyzed."
		result.summary.overall_risk = "N/A - no source"
		return result
	end

	local lines, hit_cap = split_lines(source)
	result.lines_total = #lines
	result.lines_analyzed = #lines
	if hit_cap then
		result.status = "partial"
		result.truncated = true
		result.partial_reason = string.format("The source exceeds the %d-line analysis cap; only the first %d lines were analyzed.", config.MAX_LINES, config.MAX_LINES)
	end

	local progress = opts.progress
	local yield = opts.yield
	local in_block_comment = false
	local finding_count = 0
	local next_finding = 1

	for lineno = 1, #lines do
		local raw = lines[lineno]
		local code, still_block = effective_code(raw, in_block_comment)
		in_block_comment = still_block

		for _, r in ipairs(rules.LIST) do
			local hit = false
			if r.custom then
				hit = (not r.skip_comments or #util.trim(raw) > 0) and r.custom(raw) or false
			else
				if not (r.skip_comments and #util.trim(code) == 0) then
					for _, pat in ipairs(r.patterns) do
						if string.find(code, pat) then hit = true break end
					end
				end
			end
			if hit then
				finding_count += 1
				if finding_count > config.MAX_FINDINGS then
					finding_count = config.MAX_FINDINGS
					result.truncated = true
					result.partial_reason = (result.partial_reason and result.partial_reason .. " " or "") ..
						string.format("The findings cap (%d) was reached; later findings were not recorded.", config.MAX_FINDINGS)
					break
				end
				local snippet = util.clean_text(raw, config.MAX_EVIDENCE_LEN)
				result.findings[next_finding] = {
					id = string.format("%03d", next_finding),
					rule_id = r.id, title = r.title, category = r.category,
					severity = r.severity, confidence = r.confidence,
					line = lineno, evidence = snippet,
					explanation = r.explanation, impact = r.impact, recommendation = r.recommendation,
					correlated_by = nil,
				}
				next_finding += 1
			end
		end

		if finding_count >= config.MAX_FINDINGS then break end
		if progress and lineno % config.PROGRESS_EVERY == 0 then progress("scanning", lineno, #lines) end
		if yield and lineno % config.YIELD_EVERY == 0 then yield() end
	end

	-- dedupe: the same rule firing many times on identical lines is collapsed per (rule, line)
	local seen = {}
	local unique = {}
	for _, f in ipairs(result.findings) do
		local key = f.rule_id .. "|" .. f.line
		if not seen[key] then
			seen[key] = true
			unique[#unique + 1] = f
		end
	end
	result.findings = unique

	-- correlation pass: escalate + annotate
	local has = {}
	for _, f in ipairs(result.findings) do has[f.rule_id] = f end
	for _, cor in ipairs(rules.CORRELATIONS) do
		local all = true
		for _, rid in ipairs(cor.requires) do
			if not has[rid] then all = false break end
		end
		if all then
			local anchor = has[cor.requires[1]]
			anchor.correlated_by = cor.id
			anchor.explanation = anchor.explanation .. " [" .. cor.title .. ": " .. cor.rationale .. "]"
			if SEV_RANK[cor.escalate_to] > SEV_RANK[anchor.severity] then
				anchor.severity = cor.escalate_to
			end
		end
	end

	-- summary
	local counts = { CRITICAL = 0, HIGH = 0, MEDIUM = 0, LOW = 0, INFORMATIONAL = 0 }
	for _, f in ipairs(result.findings) do
		counts[f.severity] = (counts[f.severity] or 0) + 1
	end
	result.summary.counts = counts
	result.summary.total = #result.findings
	result.summary.overall_risk = overall_risk(counts)

	-- findings ordered by severity (worst first), then line
	table.sort(result.findings, function(a, b)
		local ra, rb = SEV_RANK[a.severity], SEV_RANK[b.severity]
		if ra ~= rb then return ra > rb end
		if a.line ~= b.line then return a.line < b.line end
		return a.rule_id < b.rule_id
	end)
	for i, f in ipairs(result.findings) do f.id = string.format("%03d", i) end
	return result
end

E.SEVERITY_RANK = SEV_RANK
return E
end
__factories["src.static_rules"] = function(require)
-- Detection rules for Luau SOURCE analysis. Static analysis observes TEXT only: it can prove that a pattern
-- is present, never how it behaves at runtime. Every rule therefore states its confidence that the pattern
-- is present, and findings use hedged impact language ("potential", "may"). A single suspicious keyword is
-- never Critical by itself - severity escalates through the correlation pass in engine.lua.
--
-- Rule fields: id, title, category, severity, confidence ("low"|"medium"|"high"), patterns (Luau patterns,
-- matched case-sensitively against the RAW line), skip_comments (default true), explanation, impact,
-- recommendation.
local R = {}

R.VERSION = "1"

local function rule(id, title, category, severity, confidence, patterns, explanation, impact, recommendation, opts)
	local r = {
		id = id, title = title, category = category, severity = severity, confidence = confidence,
		patterns = patterns, explanation = explanation, impact = impact, recommendation = recommendation,
		skip_comments = true,
	}
	if opts then
		for k, v in pairs(opts) do r[k] = v end
	end
	return r
end

R.LIST = {

	-- ---------------------------------------------------------------- dynamic code execution
	rule("SS-DYN-001", "Dynamic code execution via loadstring", "Dynamic code execution", "MEDIUM", "high",
		{ "loadstring%s*%(", "loadstring%s*%.%." },
		"loadstring compiles a string into executable code while the program runs. Reading what it compiles requires seeing the argument at runtime, which static analysis cannot do.",
		"Loading code from a variable, a network response or a decoded blob executes unreviewed code and is the classic stage of obfuscated or dropped payloads.",
		"Remove dynamic compilation; if unavoidable, compile only string literals that are reviewed in the same file and document them."),

	rule("SS-DYN-002", "Environment access via getfenv/setfenv", "Unsafe environment manipulation", "LOW", "medium",
		{ "getfenv%s*%(", "setfenv%s*%(" },
		"getfenv/setfenv read or replace a function's environment table, which changes which globals its code sees.",
		"Environment swapping can hide behaviour from reviewers, defeat sandboxes or redirect global lookups to attacker-chosen tables.",
		"Avoid environment manipulation; scope values explicitly through parameters and upvalues instead."),

	rule("SS-ENV-001", "Shared global state via getgenv", "Unsafe environment manipulation", "INFORMATIONAL", "high",
		{ "getgenv%s*%(", "getgenv%s*%." },
		"getgenv exposes a global table shared across every script in the executor environment.",
		"Values planted here are readable (and replaceable) by all other scripts, which can leak data or let another script tamper with this one's state.",
		"Keep state local to the script; use getgenv only for deliberate, documented sharing."),

	-- ---------------------------------------------------------------- network
	rule("SS-NET-001", "Outbound network capability", "Remote communication", "MEDIUM", "high",
		{ "http_request%s*%(", "request%s*%(%s*%{", "game:GetService%(\"HttpService\"%)", "HttpService%s*:", "HttpGet%s*%(", "HttpPost%s*%(", "syn%s*%.%s*request", "http%s*%.%s*request" },
		"The code contains an outbound HTTP call. The destination and payload are runtime values that static analysis cannot confirm.",
		"Network access from an executor script is how data leaves the machine or remote code arrives; whether this use is legitimate cannot be proven statically.",
		"Document every destination. For audited products, remove outbound calls or restrict them to reviewed, pinned endpoints."),

	rule("SS-NET-002", "Request to a paste or webhook endpoint", "Remote communication", "HIGH", "high",
		{ "discord%s*%.%s*com%s*/%s*api%s*/%s*webhooks", "hooks%s*%.%s*slack%s*%.%s*com", "pastebin%s*%.%s*com", "hastebin", "requestbin", "webhook%s*%.%s*site", "discordapp%s*%.%s*com" },
		"The code references a paste site or webhook endpoint. These are commonly used to exfiltrate collected data or to host code fetched for loadstring.",
		"Data posted to a webhook or paste endpoint is readable by whoever owns that endpoint. A fetched paste combined with loadstring is a remote code delivery chain.",
		"Remove the endpoint. If the script legitimately reports to your own logging service, pin the exact URL, document it, and keep the payload free of user data."),

	rule("SS-NET-003", "Encoded payload fetched or built at runtime", "Obfuscation indicators", "HIGH", "medium",
		{ "[Hh]ttpGet%s*%(%s*.-[Ll]oadstring", "[Ll]oadstring%s*%(%s*.-[Hh]ttpGet", "game%s*:%s*HttpGet%s*%(%s*.-)%s*%)%s*%(%s*%)" },
		"A network fetch and code compilation appear on the same line or expression - the classic remote loadstring chain.",
		"Whatever the endpoint returns is executed as code. The endpoint content can change at any time; static analysis cannot review it.",
		"Pin the remote code to a reviewed version, ship it as part of the script, or remove the chain entirely."),

	-- ---------------------------------------------------------------- credentials
	rule("SS-CRED-001", "Access to authentication cookies or tokens", "Credential access", "CRITICAL", "high",
		{ "\.ROBLOSECURITY", "ROBLOSECURITY", "GetCookie", "%.cookie", "Authorization%s*=%s*\"Bearer", "identity%s*%.%s*cookie" },
		"The code references Roblox authentication cookies or bearer tokens.",
		"An authentication cookie grants full control of the account it belongs to. Scripts that read it and have network access can silently hijack sessions; this combination escalates to a credential exfiltration chain.",
		"Remove credential access entirely. No legitimate auditing script needs authentication material."),

	rule("SS-CRED-002", "Executor or account identity probing", "Credential access", "MEDIUM", "medium",
		{ "identifyexecutor%s*%(", "getexecutorname%s*%(", "GetUserId%s*%(", "LocalPlayer%s*%.%s*UserId" },
		"The code reads executor identity or the local player's account identifiers.",
		"By itself this is often benign UI customization, but combined with network calls it becomes user fingerprinting or tracking.",
		"Keep identity reads local to the UI; never transmit them."),

	-- ---------------------------------------------------------------- persistence
	rule("SS-PER-001", "Persistence across teleports or sessions", "Persistence", "HIGH", "high",
		{ "queue_on_teleport%s*%(", "queue%s*on%s*teleport" },
		"queue_on_teleport schedules code to run again automatically after the player moves to another server.",
		"Code that re-executes itself across servers survives the user leaving the current place - behaviour users do not expect from a script they ran once.",
		"Remove automatic re-queuing; if continuation is genuinely required, ask the user each time."),

	rule("SS-PER-002", "Write to startup or auto-execute locations", "Persistence", "HIGH", "high",
		{ "writefile%s*%(%s*\".-autoexec", "writefile%s*%(%s*\".-startup", "writefile%s*%(%s*\".-autosave", "writefile%s*%(%s*\".-autorun" },
		"The code writes into a folder that executors scan for scripts to auto-load.",
		"A file in an auto-execute location runs on every future session - a persistence mechanism the user did not explicitly install.",
		"Never write into auto-executable folders. Write data files only to clearly named, user-visible locations."),

	rule("SS-FS-001", "Filesystem write", "Filesystem access", "LOW", "high",
		{ "writefile%s*%(" },
		"The code writes files to the executor's workspace.",
		"Writes are usually benign (settings, logs), but can also plant scripts for later execution; the destination matters (see the auto-execute rule).",
		"Restrict writes to documented, non-executable paths and review what is written."),

	-- ---------------------------------------------------------------- hooking / metatables
	rule("SS-HOOK-001", "Function hooking of runtime callbacks", "Hooking and interception", "MEDIUM", "high",
		{ "hookfunction%s*%(", "hookmetamethod%s*%(", "newcclosure%s*%(" },
		"The code replaces or wraps runtime functions/metamethods.",
		"Hooking changes what other code observes or receives and is the standard toolkit for interception. Some anti-cheats also flag it, which is a user-safety concern.",
		"Avoid hooks in audited code; if interception is required, document exactly what is wrapped and why."),

	rule("SS-META-001", "Metatable unlocking or replacement", "Hooking and interception", "LOW", "medium",
		{ "getrawmetatable%s*%(", "setrawmetatable%s*%(", "setreadonly%s*%(%s*.-false%s*%)" },
		"The code reads raw metatables or makes locked objects writable.",
		"Unlocking read-only tables defeats engine guarantees and often precedes tampering with engine internals.",
		"Avoid unlocking locked objects; interact with documented APIs instead."),

	-- ---------------------------------------------------------------- obfuscation
	rule("SS-OBF-001", "Very long encoded string literal", "Obfuscation indicators", "MEDIUM", "medium",
		{},
		"A single string literal longer than 160 base64-ish characters is present.",
		"Long encoded blobs typically hide code, endpoints or configuration from review. They are also occasionally legitimate embedded assets - the pattern is an indicator, not proof.",
		"Decode and review the blob, then replace it with readable, commented literals.",
		{ skip_comments = true, custom = function(raw)
			-- Luau patterns have no bounded repetition: find long base64-ish runs manually
			local best = 0
			local start, len = 1, #raw
			local run = 0
			for i = 1, len do
				local c = string.sub(raw, i, i)
				if string.match(c, "[A-Za-z0-9+/=]") then
					run += 1
					if run > best then best = run end
				else
					run = 0
				end
			end
			return best >= 160
		end }),

	rule("SS-OBF-002", "Large string.char / byte-table construction", "Obfuscation indicators", "LOW", "medium",
		{ "string%s*%.%s*char%s*%(%s*.-,%s*.-,%s*.-,%s*.-,%s*.-,", "%{ %s*%d%s*,%s*%d%s*,%s*%d%s*,%s*%d%s*,%s*%d%s*,%s*%d%s*,%s*%d%s*,%s*%d %}" },
		"Strings are assembled from numeric byte tables at runtime.",
		"Byte-table construction is a common obfuscation step (or, rarely, a legitimate embedded binary asset). Review what it builds.",
		"Replace constructed strings with readable literals after decoding them."),

	rule("SS-OBF-003", "Heavy escape-sequence string", "Obfuscation indicators", "LOW", "low",
		{ "\\%x\\%x\\%x\\%x\\%x\\x" },
		"A string contains dense hexadecimal escape sequences.",
		"Dense escapes hide readable content from casual review - typical of packed strings.",
		"Decode the string and review it; prefer readable literals."),

	-- ---------------------------------------------------------------- remote usage
	rule("SS-REM-001", "RemoteEvent / RemoteFunction usage", "Remote communication", "INFORMATIONAL", "high",
		{ ":FireServer%s*%(", ":InvokeServer%s*%(" },
		"The code communicates with the server through a RemoteEvent or RemoteFunction.",
		"Normal in Roblox development. It becomes a review item only when the arguments include sensitive material or the endpoints are undocumented - static analysis cannot see the server-side handler.",
		"Document which remotes the script calls and with what arguments."),

	rule("SS-CLIP-001", "Clipboard write", "Data collection", "LOW", "high",
		{ "setclipboard%s*%(" },
		"The code writes to the clipboard.",
		"Usually a convenience feature; combined with collected data or credentials it becomes an exfiltration path.",
		"Only copy data the user explicitly asked to copy."),

	rule("SS-EXEC-001", "Iteration over all scripts or bytecode access", "Unsafe environment manipulation", "MEDIUM", "high",
		{ "getscripts%s*%(", "getscriptbytecode", "decompile%s*%(" },
		"The code enumerates scripts or reads their bytecode/decompilation.",
		"Sweeping every script in a game is reconnaissance for tampering or theft and typically violates the game owner's terms regardless of intent.",
		"Remove enumeration of other people's scripts; analyze only source you are authorized to inspect."),
}

R.BY_ID = {}
for _, r in ipairs(R.LIST) do R.BY_ID[r.id] = r end

-- correlation rules: evaluated by the engine over the whole file's indicator set. A correlation NEVER
-- invents a finding on its own - it escalates or annotates existing hits with a combined rationale.
R.CORRELATIONS = {
	{
		id = "SS-COR-001", title = "Remote code load chain (network -> loadstring)",
		requires = { "SS-NET-001", "SS-DYN-001" }, escalate_to = "HIGH",
		rationale = "A network fetch and dynamic compilation appear in the same file: whatever the endpoint returns can be executed as code. Review the fetched content and pin it.",
	},
	{
		id = "SS-COR-002", title = "Potential credential exfiltration chain (credential access + network)",
		requires = { "SS-CRED-001", "SS-NET-001" }, escalate_to = "CRITICAL",
		rationale = "Credential material and outbound network calls appear in the same file. Static analysis cannot prove data flows between them, but the combination is the classic session-hijacking chain and must be reviewed first.",
	},
	{
		id = "SS-COR-003", title = "Persistence chain (auto-execute write or teleport queue + dynamic execution)",
		requires = { "SS-PER-002", "SS-DYN-001" }, escalate_to = "HIGH",
		rationale = "Files written to auto-execute locations combined with dynamic compilation would re-run unreviewed code on every future session.",
	},
	{
		id = "SS-COR-004", title = "Clipboard data path (clipboard + credential or network indicators)",
		requires = { "SS-CLIP-001", "SS-CRED-001" }, escalate_to = "HIGH",
		rationale = "Clipboard writes combined with credential access can move sensitive data to where the user (or another script) may submit it.",
	},
}

-- count of rules actually loaded (surfaced in reports as "Rules Evaluated")
function R.count()
	local n = 0
	for _ in ipairs(R.LIST) do n += 1 end
	return n
end

return R
end
__factories["src.ui"] = function(require)
-- Compact declarative UI renderer for the standalone edition (ported from the tested client/ui design
-- system, reduced to what the standalone app needs: frame/text/button/input/scroll, diff-based reuse,
-- theme tokens inline - the standalone file must not depend on external modules).
--
-- Node kinds: frame {fill,stroke,radius,clip,alpha}, text {text,size,font,color,align,wrap,truncate},
-- button {text,style,action,disabled,loading}, input {text,placeholder,action,mono,multiline}, scroll {content_h}.
-- rects are plain {x,y,w,h}; the app computes layout (tested) - the renderer only paints.
local config = require("src.config")
local util = require("src.util")

local U = {}

local COLOR = {
	bg = "#0B0E13", panel = "#141922", panel_raised = "#1A202B", sidebar = "#11151D",
	border = "#272D38", border_strong = "#3A4252", accent_soft = "#2A2450",
	text = "#F3F4F6", text_muted = "#929AAA", text_disabled = "#5F6778",
	accent = "#7565E8", accent_fill = "#6A5BE0", accent_hover = "#8678F0", accent_fill_pressed = "#5C4DCB",
	success = "#67D6A0", warning = "#E8C477", error = "#E77979", danger_hover = "#F08B8B", disabled_bg = "#181D27",
	on_accent = "#FFFFFF",
}
local FONT = { ui = "Gotham", ui_bold = "GothamBold", mono = "RobotoMono" }

function U.color(name_or_hex)
	return COLOR[name_or_hex] or name_or_hex
end

U.__index = U

-- opts: { factory = {create=fn(class)}, parent = instance, env = {Color3,UDim2,UDim,Enum}, dispatch = fn(action) }
function U.new(opts)
	local self = setmetatable({}, U)
	self.factory, self.parent, self.env, self.dispatch = opts.factory, opts.parent, opts.env, opts.dispatch
	self.entries = {} -- id -> {inst=..., children={}}
	self.root_inst = nil
	return self
end

local function hex(self, h) return self.env.Color3.fromHex(U.color(h)) end


local function tween(self, inst, properties, duration)
	local service, info = self.env.TweenService, self.env.TweenInfo
	if service and info and self.env.Enum then
		local ok, tw = pcall(function()
			return service:Create(inst, info.new(duration or 0.12,
				self.env.Enum.EasingStyle.Quad, self.env.Enum.EasingDirection.Out), properties)
		end)
		if ok and tw then
			local played = pcall(function() tw:Play() end)
			if played then return true end
		end
	end
	for key, value in pairs(properties) do pcall(function() inst[key] = value end) end
	return false
end

local function button_bg(self, node, hovered)
	local style = node.style or "secondary"
	if node.disabled or node.loading then return hex(self, "disabled_bg") end
	if style == "primary" then return hex(self, hovered and "accent_hover" or "accent_fill") end
	if style == "danger" then return hex(self, hovered and "danger_hover" or "error") end
	return hex(self, hovered and "border_strong" or "panel_raised")
end

local function set_button_hover(self, entry, hovered)
	local node = entry.node
	if not node or node.kind ~= "button" or node.disabled or node.loading then return end
	tween(self, entry.inst, { BackgroundColor3 = button_bg(self, node, hovered) }, 0.12)
end

local function class_for(node)
	if node.kind == "text" then return "TextLabel" end
	if node.kind == "button" then return "TextButton" end
	if node.kind == "input" then return "TextBox" end
	if node.kind == "scroll" then return "ScrollingFrame" end
	return "Frame"
end

local function set_corner(self, entry, radius)
	if (radius or 0) > 0 then
		if not entry.corner then
			entry.corner = self.factory.create("UICorner")
			entry.corner.Parent = entry.inst
		end
		entry.corner.CornerRadius = self.env.UDim.new(0, radius)
	elseif entry.corner then
		entry.corner:Destroy()
		entry.corner = nil
	end
end

local function set_stroke(self, entry, color)
	if color then
		if not entry.stroke then
			entry.stroke = self.factory.create("UIStroke")
			entry.stroke.Parent = entry.inst
			entry.stroke.Thickness = 1
			entry.stroke.ApplyStrokeMode = self.env.Enum.ApplyStrokeMode.Border
		end
		entry.stroke.Color = hex(self, color)
	elseif entry.stroke then
		entry.stroke:Destroy()
		entry.stroke = nil
	end
end

local SEV_COLOR = { CRITICAL = "error", HIGH = "warning", MEDIUM = "warning", LOW = "text_muted", INFORMATIONAL = "text_muted" }

local function apply(self, entry, node)
	local inst, env = entry.inst, self.env
	local rect = node.rect
	local position, size = env.UDim2.fromOffset(rect.x, rect.y), env.UDim2.fromOffset(rect.w, rect.h)
	local previous = entry.rect
	if node.animate and previous and (previous.x ~= rect.x or previous.y ~= rect.y or previous.w ~= rect.w or previous.h ~= rect.h) then
		tween(self, inst, { Position = position, Size = size }, 0.22)
	else
		inst.Position = position
		inst.Size = size
	end
	entry.rect = { x = rect.x, y = rect.y, w = rect.w, h = rect.h }
	inst.BorderSizePixel = 0
	entry.node = node

	if node.kind == "frame" then
		inst.BackgroundColor3 = hex(self, node.fill or "panel")
		inst.BackgroundTransparency = node.fill and (1 - (node.alpha or 1)) or 1
		inst.ClipsDescendants = node.clip == true
		set_corner(self, entry, node.radius)
		set_stroke(self, entry, node.stroke)
	elseif node.kind == "text" then
		inst.BackgroundColor3 = hex(self, node.fill or "bg")
		inst.BackgroundTransparency = node.fill and 0 or 1
		local color = node.color and U.color(node.color) or "text"
		if SEV_COLOR[node.color] then color = node.color end
		inst.TextColor3 = hex(self, color)
		inst.TextSize = node.size or 13
		inst.Font = self.env.Enum.Font[FONT[node.font or "ui"]]
		inst.Text = node.text or ""
		inst.TextXAlignment = node.align == "right" and self.env.Enum.TextXAlignment.Right
			or (node.align == "center" and self.env.Enum.TextXAlignment.Center or self.env.Enum.TextXAlignment.Left)
		inst.TextYAlignment = self.env.Enum.TextYAlignment.Top
		inst.TextWrapped = node.wrap == true
		inst.RichText = false
		if node.truncate then
			inst.TextTruncate = self.env.Enum.TextTruncate.AtEnd
		else
			inst.TextTruncate = self.env.Enum.TextTruncate.None
		end
		inst.ClipsDescendants = true
	elseif node.kind == "button" then
		local style = node.style or "secondary"
		local disabled = node.disabled or node.loading
		inst.BackgroundColor3 = button_bg(self, node, false)
		inst.TextColor3 = hex(self, (style == "primary" or style == "danger") and "on_accent" or (disabled and "text_disabled" or "text"))
		inst.TextSize = 13
		inst.Font = self.env.Enum.Font[FONT.ui]
		inst.Text = node.loading and (node.busy_text or "Working...") or (node.text or "")
		inst.AutoButtonColor = false
		inst.ClipsDescendants = true
		set_corner(self, entry, 4)
		set_stroke(self, entry, style == "secondary" and "border_strong" or nil)
		inst.Active = not disabled
		-- click wiring happens once at creation; disabled state is checked via entry.node at dispatch time
	elseif node.kind == "input" then
		inst.BackgroundColor3 = hex(self, "bg")
		inst.PlaceholderColor3 = hex(self, "text_disabled")
		inst.TextColor3 = hex(self, "text")
		inst.TextSize = 13
		inst.Font = self.env.Enum.Font[FONT[node.mono and "mono" or "ui"]]
		inst.Text = node.text or ""
		inst.PlaceholderText = node.placeholder or ""
		inst.TextEditable = true
		inst.ClearTextOnFocus = false
		inst.TextWrapped = false
		inst.MultiLine = node.multiline == true
		inst.TextXAlignment = self.env.Enum.TextXAlignment.Left
		inst.TextYAlignment = node.multiline and self.env.Enum.TextYAlignment.Top or self.env.Enum.TextYAlignment.Center
		set_stroke(self, entry, "border_strong")
	elseif node.kind == "scroll" then
		inst.BackgroundColor3 = hex(self, node.fill or "bg")
		inst.BorderSizePixel = 0
		inst.ScrollBarThickness = 6
		inst.ScrollBarImageColor3 = hex(self, "border_strong")
		inst.CanvasSize = env.UDim2.fromOffset(0, node.content_h or 0)
		inst.AutomaticCanvasSize = env.Enum.AutomaticSize.None
		inst.ClipsDescendants = true
	end
end

-- wire interactive instances once (clicks dispatch through entry so the CURRENT node state is checked)
local function wire(self, entry, node)
	if node.kind == "button" and not entry.wired then
		entry.wired = true
		entry.inst.MouseButton1Click:Connect(function()
			local n = entry.node
			if n and not n.disabled and not n.loading and n.action then
				self.dispatch(n.action)
			end
		end)
		pcall(function()
			entry.inst.MouseEnter:Connect(function() set_button_hover(self, entry, true) end)
			entry.inst.MouseLeave:Connect(function() set_button_hover(self, entry, false) end)
		end)
	elseif node.kind == "input" and not entry.wired then
		entry.wired = true
		entry.inst.FocusLost:Connect(function(enter)
			local n = entry.node
			if n and n.action then
				n.action.arg = n.action.arg_enter and (enter and entry.inst.Text or nil) or entry.inst.Text
				if n.action.take_text ~= false then n.text = entry.inst.Text end
				self.dispatch(n.action)
			end
		end)
	end
end

local function build_children(self, node, parent_entry)
	local by_id = {}
	local old = parent_entry and parent_entry.children or {}
	for id, e in pairs(old) do by_id[id] = e end
	local keep = {}
	for _, child in ipairs(node.children or {}) do
		keep[child.id] = true
		local e = by_id[child.id]
		if e and e.inst.Parent then
			apply(self, e, child)
			wire(self, e, child)
			build_children(self, child, e)
		else
			local inst = self.factory.create(class_for(child))
			inst.Name = child.id
			inst.Parent = parent_entry and parent_entry.inst or self.parent
			local ne = { inst = inst }
			apply(self, ne, child)
			wire(self, ne, child)
			build_children(self, child, ne)
			e = ne
		end
		parent_entry.children = parent_entry.children or {}
		parent_entry.children[child.id] = e
	end
	-- destroy nodes that vanished (diff cleanup; also drops their connections by destruction)
	if parent_entry then
		for id, e in pairs(by_id) do
			if not keep[id] then
				pcall(function() e.inst:Destroy() end)
				parent_entry.children[id] = nil
			end
		end
	end
end

-- render(root_node): diff the previous tree; unchanged nodes reuse instances (no flicker, no leaks)
function U:render(root)
	if not self.root_inst then
		self.root_inst = self.factory.create(class_for(root))
		self.root_inst.Name = root.id
		self.root_inst.Parent = self.parent
		self.root = { inst = self.root_inst, children = {} }
	end
	apply(self, self.root, root)
	build_children(self, root, self.root)
end

function U:destroy()
	-- walk and disconnect is unnecessary for Roblox (Destroy disconnects), but the mock tracks it:
	local function drop(e)
		if e.children then
			for _, c in pairs(e.children) do drop(c) end
		end
		pcall(function() e.inst:Destroy() end)
	end
	if self.root then drop(self.root) end
	self.root, self.root_inst, self.entries = nil, nil, {}
end

return U
end
__factories["src.util"] = function(require)
-- Small helpers shared by all modules. No module-level mutable state.
local M = {}

function M.deepcopy(v)
	if type(v) ~= "table" then return v end
	local out = {}
	for k, x in pairs(v) do out[k] = M.deepcopy(x) end
	local mt = getmetatable(v)
	if mt then setmetatable(out, mt) end
	return out
end

function M.sorted_keys(t)
	local keys = {}
	for k in pairs(t) do keys[#keys + 1] = k end
	table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
	return keys
end

function M.count(t)
	local n = 0
	for _ in pairs(t) do n += 1 end
	return n
end

function M.list_contains(list, value)
	for _, x in ipairs(list) do
		if x == value then return true end
	end
	return false
end

function M.set(list)
	local s = {}
	for _, x in ipairs(list) do s[x] = true end
	return s
end

function M.startswith(s, prefix) return string.sub(s, 1, #prefix) == prefix end

-- ---------------------------------------------------------------- time
local function days_from_civil(y, m, d)
	if m <= 2 then y -= 1 end
	local era = math.floor(y / 400)
	local yoe = y - era * 400
	local mp = (m + 9) % 12
	local doy = math.floor((153 * mp + 2) / 5) + d - 1
	local doe = yoe * 365 + math.floor(yoe / 4) - math.floor(yoe / 100) + doy
	return era * 146097 + doe - 719468
end

-- "2026-10-24T13:00:00Z" -> unix seconds (UTC) or nil when malformed.
function M.iso_to_unix(s)
	if type(s) ~= "string" then return nil end
	local y, mo, d, h, mi, se = string.match(s, "^(%d%d%d%d)%-(%d%d)%-(%d%d)T(%d%d):(%d%d):(%d%d)Z$")
	if not y then return nil end
	y, mo, d, h, mi, se = tonumber(y), tonumber(mo), tonumber(d), tonumber(h), tonumber(mi), tonumber(se)
	if mo < 1 or mo > 12 or d < 1 or d > 31 or h > 23 or mi > 59 or se > 60 then return nil end
	return days_from_civil(y, mo, d) * 86400 + h * 3600 + mi * 60 + se
end

function M.unix_to_iso(t)
	return os.date("!%Y-%m-%dT%H:%M:%SZ", math.floor(t))
end

-- UTC "YYYYMMDD_HHMMSS" stamp for export file names (e.g. ShadowScan_Audit_20261107_093012.txt)
function M.audit_stamp(t)
	return os.date("!%Y%m%d_%H%M%S", math.floor(t))
end

-- ---------------------------------------------------------------- randomness (identifiers only, never secrets)
function M.rand_hex(nbytes, rnd)
	rnd = rnd or math.random
	local out = {}
	for i = 1, nbytes do out[i] = string.format("%02x", rnd(0, 255)) end
	return table.concat(out)
end

-- ---------------------------------------------------------------- text
function M.trim(s) return (string.gsub(s, "^%s*(.-)%s*$", "%1")) end

-- Truncate to n bytes on a UTF-8 boundary and strip control characters.
function M.clean_text(s, n)
	s = tostring(s)
	s = string.gsub(s, "%c", " ")
	if #s > n then
		s = string.sub(s, 1, n)
		while #s > 0 and string.find(string.sub(s, -1), "[\128-\191]") do s = string.sub(s, 1, -2) end
		if #s > 0 and string.find(string.sub(s, -1), "[\192-\255]") then s = string.sub(s, 1, -2) end
		s = s .. "..."
	end
	return s
end

-- Split an identifier ("GiveMoneyToPlayer", "buy_item2") into lowercase alphabetic tokens.
function M.tokenize(s)
	s = tostring(s)
	s = string.gsub(s, "(%l)(%u)", "%1 %2")
	s = string.gsub(s, "(%u)(%u%l)", "%1 %2")
	local tokens = {}
	for w in string.gmatch(string.lower(s), "%a+") do tokens[#tokens + 1] = w end
	return tokens
end

-- words: set of exact tokens; prefixes: list of prefixes (>= 5 chars recommended). Returns matched token or nil.
function M.match_tokens(tokens, words, prefixes)
	for _, tok in ipairs(tokens) do
		if words and words[tok] then return tok end
		if prefixes then
			for _, p in ipairs(prefixes) do
				if string.sub(tok, 1, #p) == p then return tok end
			end
		end
	end
	return nil
end

function M.last_segment(path)
	return string.match(path, "([^%.]+)$") or path
end

function M.parent_path(path)
	return string.match(path, "^(.*)%.[^%.]+$")
end

-- severity / confidence ordering
M.SEVERITY_ORDER = { informational = 1, low = 2, medium = 3, high = 4 }
M.CONFIDENCE_ORDER = { low = 1, medium = 2, high = 3 }

function M.max_by_order(order, a, b)
	if a == nil then return b end
	if b == nil then return a end
	return (order[a] >= order[b]) and a or b
end

function M.min_by_order(order, a, b)
	return (order[a] <= order[b]) and a or b
end

-- ---------------------------------------------------------------- 0.5.0 helpers (static analyzer + export)
function M.startswith5(s, prefix) return string.sub(s, 1, #prefix) == prefix end
function M.err_message(err)
	local s = tostring(err)
	return string.match(s, ":%d+: (.+)$") or s
end
-- executor capability probe: detect, never assume (0.5.0 util)
function M.detect_caps(genvs)
	genvs = genvs or {}
	local function find(name)
		for _, g in ipairs(genvs) do
			if type(g) == "table" then
				local ok, v = pcall(function() return g[name] end)
				if ok and v ~= nil then return v end
			end
		end
		return nil
	end
	local caps = {}
	local function probe(name)
		local v = find(name)
		caps[name] = (type(v) == "function") and v or nil
		return caps[name] ~= nil
	end
	probe("setclipboard"); probe("toclipboard"); probe("writefile"); probe("readfile")
	probe("makefolder"); probe("isfolder"); probe("identifyexecutor"); probe("getexecutorname")
	caps.setclipboard = caps.setclipboard or caps.toclipboard or nil
	return caps
end
function M.describe_caps(caps, executor_name)
	local function yn(v) return v and "yes" or "NO" end
	return string.format("executor=%s clipboard=%s writefile=%s (capabilities detected at runtime; unverified claim)",
		tostring(executor_name or "unknown"), yn(caps.setclipboard), yn(caps.writefile))
end


-- UTC timestamp helpers (0.5.0)
function M.timestamp(unix)
	if os and os.date then
		return os.date("!%Y-%m-%d %H:%M:%S UTC", unix), os.date("!%Y%m%d_%H%M%S", unix)
	end
	return "unknown-time", "unknown"
end

return M
end

-- ---------------------------------------------------------------- bootstrap (runtime)
-- 0.6.2: runtime bootstrap with minimize/close lifecycle and eased UI transitions. Executing this file initializes a real application instance:
-- the session is bound to the actual Roblox `game` environment when one exists, and in a GUI-capable
-- runtime the 8-page interface is constructed with a real Instance.new factory into a ScreenGui
-- parented to the local player's PlayerGui (or an executor-exposed CoreGui hook), with the viewport
-- detected from the current camera and a Heartbeat lifecycle draining passive live observations.
-- Headless (Luau CLI, tests) no GUI is attempted and the same instance serves as the plain API.
-- The tool never executes the analyzed source, never fires remotes, never touches the network.
local config = __require("src.config")
local ShadowScanModule = __require("src.main")

local function detect_game()
	local ok, g = pcall(function() return game end)
	if ok and g ~= nil and (type(g) == "userdata" or type(g) == "table") then return g end
	return nil
end

local function probe_global_envs()
	local envs = {}
	local okg, gv = pcall(function() return (getgenv and getgenv()) end)
	if okg and type(gv) == "table" then envs[#envs + 1] = gv end
	local okf, fv = pcall(function() return (getfenv and getfenv(1)) end)
	if okf and type(fv) == "table" then envs[#envs + 1] = fv end
	local okG, Gv = pcall(function() return _G end)
	if okG and type(Gv) == "table" then envs[#envs + 1] = Gv end
	return envs
end

local function detect_gui_parent(game)
	-- 1) executor-exposed CoreGui hook (gethui)
	local okh, hui = pcall(function() return (gethui and gethui()) end)
	if okh and hui ~= nil then return hui, "coregui-hook" end
	-- 2) the supported path: the local player's PlayerGui
	local okp, players = pcall(function() return game:GetService("Players") end)
	if okp and players ~= nil then
		local okl, lp = pcall(function() return players.LocalPlayer end)
		if okl and lp ~= nil then
			local okw, pg = pcall(function()
				return lp:FindFirstChild("PlayerGui")
					or (type(lp.WaitForChild) == "function" and lp:WaitForChild("PlayerGui", 5) or nil)
			end)
			if okw and pg ~= nil then return pg, "PlayerGui" end
		end
	end
	-- 3) direct CoreGui access (some executors allow it)
	local okc, cg = pcall(function() return game:GetService("CoreGui") end)
	if okc and cg ~= nil then return cg, "CoreGui" end
	return nil, nil
end

local function detect_viewport(game)
	local ok, vs = pcall(function()
		local ws = game:GetService("Workspace")
		local cam = ws and ws.CurrentCamera
		return cam and cam.ViewportSize or nil
	end)
	-- ViewportSize is a Vector2 (userdata) in Roblox; mock environments return tables. Both index .X/.Y.
	if ok and vs ~= nil and vs.X ~= nil and vs.Y ~= nil and vs.X > 0 and vs.Y > 0 then
		return { w = math.floor(vs.X), h = math.floor(vs.Y) }
	end
	return nil
end

local function make_screen_gui(parent)
	local ok, sg = pcall(function()
		local g = Instance.new("ScreenGui")
		g.Name = "ShadowScanUI"
		g.ResetOnSpawn = false
		g.DisplayOrder = 1000
		g.IgnoreGuiInset = true
		g.Parent = parent
		return g
	end)
	if ok and sg ~= nil then return sg end
	return nil
end

local function attach_lifecycle(inst, game, screen)
	local ok, rs = pcall(function() return game:GetService("RunService") end)
	if not ok or rs == nil or rs.Heartbeat == nil then return nil end
	local okc, conn = pcall(function()
		return rs.Heartbeat:Connect(function()
			local okt, changed = pcall(function() return inst:tick() end)
			if okt and changed == true and inst.app ~= nil then
				pcall(function() inst.app:render() end)
			end
		end)
	end)
	if okc and conn ~= nil then
		pcall(function()
			screen.Destroying:Connect(function()
				pcall(function() conn:Disconnect() end)
				pcall(function() inst:destroy(true) end)
			end)
		end)
		return conn
	end
	return nil
end

local BOOT = { game_detected = false, gui = false, gui_parent = nil, viewport = nil, lifecycle = false, error = nil }
local instance, screen_gui, lifecycle_conn = nil, nil, nil
local game_env = detect_game()
BOOT.game_detected = game_env ~= nil

local ok_boot, boot_err = pcall(function()
	local opts = { globals_envs = probe_global_envs(), game = game_env }
	if game_env ~= nil then
		local parent, kind = detect_gui_parent(game_env)
		BOOT.gui_parent = kind
		if parent ~= nil then
			local screen = make_screen_gui(parent)
			if screen ~= nil then
				screen_gui = screen
				opts.gui = {
					parent = screen,
					factory = { create = function(class) return Instance.new(class) end },
					env = { Color3 = Color3, UDim2 = UDim2, UDim = UDim, Enum = Enum,
                        TweenService = (function()
                            local ok_service, service = pcall(function() return game_env:GetService("TweenService") end)
                            return ok_service and service or nil
                        end)(), TweenInfo = TweenInfo },
					viewport = detect_viewport(game_env),
					on_close = function()
						if lifecycle_conn then pcall(function() lifecycle_conn:Disconnect() end) lifecycle_conn = nil end
						local old_screen = screen_gui
						screen_gui = nil
						if old_screen then pcall(function() old_screen:Destroy() end) end
						if instance then pcall(function() instance:destroy(true) end) end
					end,
				}
				BOOT.viewport = opts.gui.viewport
			end
		end
	end
	instance = ShadowScanModule.new(opts)
	if instance.app ~= nil and screen_gui ~= nil then
		lifecycle_conn = attach_lifecycle(instance, game_env, screen_gui)
		BOOT.lifecycle = lifecycle_conn ~= nil
	end
end)
if not ok_boot then BOOT.error = tostring(boot_err) end
-- absolute fallback: the console object must always have a working backend, even if bootstrap failed
if instance == nil then instance = ShadowScanModule end

local ShadowScan = {}
ShadowScan.VERSION = config.VERSION
ShadowScan.module = ShadowScanModule
ShadowScan.instance = instance
ShadowScan.session = instance.session
ShadowScan.BOOT = BOOT

function ShadowScan.analyze(source, name)
	return instance:analyze(source, name)
end

function ShadowScan.report_text(source, name)
	-- With a source string: STATIC analysis report of that source (the source is never executed).
	-- Without: the combined runtime report of the live session. 0.6.0 forwarded (source, name) into
	-- the combined-report method, silently dropping the static findings from the returned text.
	if type(source) == "string" and #source > 0 then
		return instance:static_report_text(source, name)
	end
	return instance:report_text()
end

function ShadowScan.describe()
	-- never throws: a loader that only inspects the result cannot crash on this function
	local ok, text = pcall(instance.describe, instance)
	if ok and type(text) == "string" then return text end
	return "ShadowScan " .. config.VERSION .. " (" .. config.EDITION .. ")"
end

function ShadowScan.open_ui()
	if instance and instance.app then
		instance.app:restore()
		return instance.app
	end
	return nil, BOOT.error
		or "no GUI environment was detected at load time; the UI needs a Roblox runtime with PlayerGui or CoreGui access"
end

function ShadowScan.request_cancel()
	if instance and instance.session and instance.session.request_cancel then
		return instance.session:request_cancel()
	end
	return false
end

function ShadowScan.destroy()
	if instance then pcall(function() instance:destroy(true) end) end
	if lifecycle_conn then pcall(function() lifecycle_conn:Disconnect() end) lifecycle_conn = nil end
	local old_screen = screen_gui
	screen_gui = nil
	if old_screen then pcall(function() old_screen:Destroy() end) end
end

print(string.format("[ShadowScan] v%s loaded - UI: %s - %s", config.VERSION,
	(instance.app) and ("constructed (" .. tostring(BOOT.gui_parent) .. ")") or "not constructed (console mode)",
	ShadowScan.describe()))

return ShadowScan
